window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch05"]={"id":"ch05","title":"第三章(三) 后翻译转运","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"线粒体/叶绿体 · 核孔运输 · 过氧化物酶体","modules":[{"i":0,"name":"模块一：线粒体与叶绿体蛋白转运","slides":[{"i":0,"sec":"第一节 线粒体","title":"Part III 后翻译转运 (p1)","notes":"Part III The transport protein into Mitochondria(线粒体)、Chloroplast(叶绿体) and Peroxisome(过氧化物酶体)。线粒体/叶绿体的绝大多数蛋白质由核基因编码、细胞质游离核糖体合成，然后定向运输(翻译后转移)。","page":1,"level":"掌握","img":"assets/img/ch05/p001.jpg","anim":null,"fig":null,"points":["后翻译转运：将蛋白运入线粒体、叶绿体、过氧化物酶体","线粒体/叶绿体绝大多数蛋白由核基因编码、胞质游离核糖体合成后定向运输"],"check":{"q":"关于线粒体、叶绿体蛋白质的合成与运输，正确的是？","o":["A. 绝大多数蛋白由自身基因组编码并在细胞器内合成","B. 全部蛋白由内质网附着核糖体合成后转运","C. 绝大多数蛋白由核基因编码、细胞质游离核糖体合成后转运","D. 蛋白不经运输直接在细胞器内合成"],"a":"C","e":"线粒体、叶绿体的绝大多数蛋白质由核基因编码，在细胞质游离核糖体上合成，然后定向运输（翻译后转移）进入细胞器。","oe":["恰好相反，绝大多数由核基因编码，故错误。","为翻译后转运，不经内质网附着核糖体。","正确，核基因编码、游离核糖体合成后转运。","蛋白须跨膜转运进入细胞器，故错误。"]},"cards":[{"front":"线粒体、叶绿体和过氧化物酶体的大多数蛋白质由什么编码、在哪里合成、以何种方式运输？","back":"由核基因编码；在细胞质游离核糖体合成；翻译后定向运输（后转运）","mnemonic":"核编码、胞质造、译后送","type":"流程","useImg":false,"blank":"翻译后定向运输","blank2":"细胞质游离核糖体"}],"mem":"核编码、胞质造、译后送","big":"assets/img/ch05/big/p001.jpg","summary":"Part III The transport protein into Mitochondria(线粒体)、Chloroplast(叶绿体) and Peroxisome(过氧化物","goal":"学完应能掌握并运用「Part III 后翻译转运」的核心内容，能解释其机制、比较相关概念。","intuition":"后翻译转运像“给蛋白发目的地票”：线粒体、叶绿体、过氧化物酶体的多数蛋白由核基因编码，在胞质造好后再定向送入。"},{"i":1,"sec":"第一节 线粒体","title":"线粒体蛋白的定向运输 (p2)","notes":"线粒体蛋白质的定向运输(eg.定位于线粒体基质中的蛋白)：一、后转运的跨膜运输——线粒体蛋白质的定向运输。线粒体虽有自己的基因组，但绝大多数蛋白由核基因编码。","page":2,"level":"掌握","img":"assets/img/ch05/p002.jpg","anim":null,"fig":"线粒体蛋白的定向运输：线粒体绝大多数蛋白由核基因编码，在胞质游离核糖体合成后以“前体蛋白”形式运入。前体蛋白 N 端有导肽，识别线粒体膜上的受体。图显示前体蛋白从胞质进入线粒体的过程。","points":["线粒体虽有自己的基因组，但绝大多数蛋白由核基因编码","通过后转运的跨膜运输定位于线粒体"],"check":{"q":"线粒体蛋白质定向运输的特点之一是？","o":["A. 属于后转运的跨膜运输，蛋白合成后转运","B. 属于共翻译转运，需信号识别颗粒","C. 全部在线粒体内合成，无需转运","D. 仅由线粒体自身基因编码"],"a":"A","e":"线粒体蛋白质定向运输属于后转运的跨膜运输；线粒体虽有自己的基因组，但绝大多数蛋白由核基因编码，合成后再转运入线粒体。","oe":["正确，线粒体蛋白属后转运的跨膜运输，合成后再转运。","属后转运而非共翻译转运，也不需要SRP。","绝大多数蛋白在胞质合成后转运，故错误。","绝大多数由核基因编码，非自身基因。"]},"cards":[{"front":"线粒体蛋白质定向运输的主要方式是什么？","back":"后转运的跨膜运输；线粒体虽有自身基因组，但绝大多数蛋白由核基因编码","mnemonic":"自有DNA，蛋白靠核供","type":"定义","useImg":false,"blank":"后转运的跨膜运输","blank2":"核基因编码"}],"mem":"自有DNA，蛋白靠核供","big":"assets/img/ch05/big/p002.jpg","summary":"线粒体蛋白质的定向运输(eg.定位于线粒体基质中的蛋白)：一、后转运的跨膜运输——线粒体蛋白质的定向运输","goal":"学完应能掌握并运用「线粒体蛋白的定向运输」的核心内容，能解释其机制、比较相关概念。","intuition":"线粒体虽自带一点 DNA，但绝大多数蛋白是“外包生产”：核基因编码→胞质核糖体合成→翻译后运入线粒体。"},{"i":2,"sec":"第一节 线粒体","title":"线粒体蛋白运输要点 (p3)","notes":"线粒体蛋白定向运输要点：①N端导肽(presequence)必须先与线粒体膜上的受体识别；②前体蛋白到线粒体基质的转移只发生在少数线粒体内外膜相'接触点'(距约若干nm)。","page":3,"level":"掌握","img":"assets/img/ch05/p003.jpg","anim":"mito_import","fig":null,"points":["N 端导肽先与线粒体膜受体识别。","前体蛋白以解析叠形式穿过 TOM/TIM，在接触点(内外膜贴近处)转位。","转运消耗能量：胞质 Hsp70、膜电位、基质 Hsp70 与 ATP。","进入基质后导肽被切除，蛋白折叠成成熟形式。"],"check":{"q":"线粒体蛋白定向运输的要点，下列正确的是？","o":["A. N端导肽先与线粒体膜上受体识别","B. 前体蛋白可在线粒体膜任意位置进入基质","C. 导肽位于C端，进入基质后保留","D. 转运不需要能量，蛋白以折叠状态进入"],"a":"A","e":"线粒体蛋白定向运输时，N端导肽必须先与线粒体膜上的受体识别；前体蛋白到基质的转移只发生在少数内外膜接触点，且需能量。","oe":["正确，N端导肽先与线粒体膜受体识别。","转移只发生在内外膜接触点，非任意位置。","导肽位于N端且进入后被切除，故错误。","转运需能量且蛋白以解析叠形式进入。"]},"cards":[{"front":"线粒体蛋白定向运输的两个要点是什么？","back":"①N端导肽先与线粒体膜受体识别；②前体蛋白仅在内外膜接触点转移到基质","mnemonic":"导肽认受体，接触点进门","type":"流程","useImg":false,"blank":"N端导肽","blank2":"线粒体膜受体"}],"mem":"导肽认受体，接触点进门","big":"assets/img/ch05/big/p003.jpg","summary":"线粒体蛋白定向运输要点：①N端导肽(presequence)必须先与线粒体膜上的受体识别；②前体蛋白到线粒体基质的转移只发生在少数线粒体内外膜相'接触点'(距约若干nm)","goal":"学完应能掌握并运用「线粒体蛋白运输要点」的核心内容，能解释其机制、比较相关概念。","intuition":"进线粒体三要点：要带导肽（地址）、要保持去折叠（能钻窄通道）、要耗能（Hsp70 等帮忙）。"},{"i":3,"sec":"第一节 线粒体","title":"接触点转运 (p4)","notes":"Translocation of protein precursors to the matrix occurs at the contact sites——前体蛋白在内外膜接触点处转运到线粒体基质。接触点是内外膜靠近的区域。\n\n【本页英文讲解】\n本页讲线粒体蛋白的接触点转运（contact site）。前体蛋白（protein precursor）从细胞质转运进线粒体基质（matrix）时，并非在膜上任意位置进行，而是在内外膜相互靠近的接触点（contact sites）。此处使外膜与内膜的转运装置靠拢，便于前体蛋白穿越两层膜。考点：接触点是线粒体蛋白跨膜转运的通道位点，常与TOM/TIM协同。","page":4,"level":"掌握","img":"assets/img/ch05/p004.jpg","anim":null,"fig":"前体蛋白进入线粒体基质发生在“接触点”——外膜与内膜紧密贴近的区域。图显示 TOM 与 TIM 在接触点对接，前体蛋白经此从胞质直接进入基质，避免在膜间隙停留。","points":["前体蛋白在内外膜接触点处转运到线粒体基质","接触点是内外膜相互靠近的区域"],"check":{"q":"线粒体前体蛋白转运进入基质的位置是？","o":["A. 线粒体嵴的膜间隙","B. 内外膜相互靠近的接触点","C. 线粒体DNA所在的拟核区","D. 外膜任意位置"],"a":"B","e":"前体蛋白在内外膜相互靠近的接触点处转运进入线粒体基质，此处使内外膜转运装置靠拢。","oe":["转运目的地是基质并经接触点，非嵴膜间隙，错误。","正确，前体蛋白在内外膜接触点处转运入基质。","拟核区不参与前体蛋白转运通道，错误。","转运并非在外膜任意位置，而在接触点，错误。"]},"cards":[{"front":"前体蛋白转运到线粒体基质发生在什么部位？","back":"内外膜接触点（contact sites）；即内外膜靠近的区域","mnemonic":"两膜贴近处，就是转运门","type":"定位","useImg":true,"blank":"内外膜接触点","blank2":"内外膜靠近的区域"}],"mem":"两膜贴近处，就是转运门","big":"assets/img/ch05/big/p004.jpg","terms":[{"t":"接触点","en":"contact sites","d":"线粒体内外膜相互靠近的区域，是前体蛋白跨双层膜转运进入基质的位点。"},{"t":"线粒体基质","en":"matrix","d":"线粒体内膜以内的空间。"}],"summary":"Translocation of protein precursors to the matrix occurs at the contact sites——前体蛋白在内外膜接触点","goal":"学完应能掌握并运用「接触点转运」的核心内容，能解释其机制、比较相关概念。","intuition":"接触点像“内外膜贴到一起的过道”：前体蛋白不必分两次穿膜，而在内外膜贴近处一次通过、直达基质。"},{"i":4,"sec":"第一节 线粒体","title":"线粒体膜的转运子 (p5)","notes":"The protein translocators in the mitochondrial membrane：外膜转运子TOM复合体、内膜转运子TIM复合体。前体蛋白经TOM进入、经TIM进入基质。\n\n【本页英文讲解】\n本页介绍线粒体膜上的蛋白转运子。外膜转运子为TOM复合体（translocase of the outer membrane，外膜转运酶复合体），内膜转运子为TIM复合体（内膜转运酶复合体）。前体蛋白先经TOM穿过外膜，再经TIM穿过内膜进入基质。考点：TOM负责识别并进入外膜，TIM负责跨内膜，二者分工是线粒体蛋白导入的核心装置。","page":5,"level":"掌握","img":"assets/img/ch05/p005.jpg","anim":"tom_tim","fig":"线粒体膜上的蛋白转运器：①TOM 复合体(外膜)——受体+转位通道，接收胞质前体蛋白；②SAM 复合体(外膜)——把外膜蛋白插入外膜；③TIM23 复合体(内膜)——把蛋白送入基质，Hsp70 驱动；④TIM22 复合体(内膜)——插入内膜的载体蛋白；⑤OXA 复合体(内膜)——插入内膜蛋白。","points":["外膜转运子为TOM复合体","内膜转运子为TIM复合体","前体蛋白经TOM进入外膜、经TIM进入基质"],"check":{"q":"线粒体膜上的蛋白转运子及其分工是？","o":["A. TOM为外膜转运子，TIM为内膜转运子，前体经TOM再经TIM进基质","B. TOM位于内膜，TIM位于外膜","C. TOM与TIM均位于外膜","D. TIM负责进入外膜，TOM负责进入基质"],"a":"A","e":"外膜转运子为TOM复合体，内膜转运子为TIM复合体；前体蛋白先经TOM穿过外膜，再经TIM穿过内膜进入基质。","oe":["正确，TOM在外膜、TIM在内膜，依序转运。","定位颠倒，TOM在外膜、TIM在内膜。","TOM在外膜而TIM在内膜，非均在外膜。","分工颠倒，TOM先入外膜、TIM再入基质。"]},"cards":[{"front":"线粒体膜上的两个蛋白转运子复合体是什么？各负责什么？","back":"外膜转运子TOM复合体；内膜转运子TIM复合体；前体蛋白经TOM进入、经TIM进入基质","mnemonic":"TOM在外，TIM在内，T-O-M进，T-I-M深","type":"组成","useImg":true,"blank":"TOM复合体","blank2":"TIM复合体"}],"mem":"TOM在外，TIM在内，T-O-M进，T-I-M深","big":"assets/img/ch05/big/p005.jpg","summary":"The protein translocators in the mitochondrial membrane：外膜转运子TOM复合体、内膜转运子TIM复合体","goal":"学完应能掌握并运用「线粒体膜的转运子」的核心内容，能解释其机制、比较相关概念。","intuition":"TOM/TIM 像“两道关卡”：前体蛋白先过外膜的 TOM，再过内膜的 TIM 进入基质，两道关卡各管一层膜。"},{"i":5,"sec":"第一节 线粒体","title":"只有解折叠蛋白能进入 (p6)","notes":"Only unfolded proteins can be imported into Mit——只有去折叠的蛋白才能被导入线粒体。线粒体蛋白必须先在胞质解折叠才能穿过膜的狭窄通道。","page":6,"level":"掌握","img":"assets/img/ch05/p006.jpg","anim":null,"fig":"只有解析叠的蛋白才能进入线粒体：前体蛋白在胞质由 Hsp70 维持解析叠；进入基质时 Hsp70 结合并拉动肽链。图对比“折叠的蛋白不能进入”与“解析叠的蛋白可进入”。","points":["只有去折叠的蛋白才能被导入线粒体","蛋白必须先在胞质解折叠才能穿过膜的狭窄通道"],"check":{"q":"线粒体蛋白被导入线粒体前必须处于何种状态？","o":["A. 与溶酶体结合的状态","B. 去折叠的松散状态","C. 糖基化修饰后的状态","D. 完全折叠的天然状态"],"a":"B","e":"只有去折叠的蛋白才能被导入线粒体，线粒体蛋白须先在胞质解折叠才能穿过膜的狭窄通道。","oe":["线粒体蛋白导入与溶酶体结合无关，错误。","正确，蛋白须先去折叠才能穿过狭窄通道进入线粒体。","糖基化并非线粒体蛋白导入的前提条件，错误。","完全折叠的蛋白无法通过转运通道，错误。"]},"cards":[{"front":"为什么只有去折叠的蛋白才能被导入线粒体？","back":"线粒体蛋白须先在胞质解折叠，才能穿过膜上狭窄的通道","mnemonic":"通道太窄，折叠进不来","type":"功能","useImg":false,"blank":"解折叠","blank2":"狭窄的通道"}],"mem":"通道太窄，折叠进不来","big":"assets/img/ch05/big/p006.jpg","summary":"Only unfolded proteins can be imported into Mit——只有去折叠的蛋白才能被导入线粒体","goal":"学完应能掌握并运用「只有解折叠蛋白能进入」的核心内容，能解释其机制、比较相关概念。","intuition":"折叠好的蛋白像“搬不进窄门的大沙发”：必须先由 Hsp70 帮忙拉松（去折叠），才能穿过线粒体膜的窄通道。","experiment":"【实验】把折叠紧密的蛋白与去折叠的蛋白分别与分离线粒体孵育，结合蛋白酶保护实验。\n【结果判读】只有去折叠(或被 Hsp70 拉松)的前体能被导入；折叠紧密的蛋白不能穿过 TOM/TIM 通道——证明线粒体蛋白必须解折叠后导入。"},{"i":6,"sec":"第一节 线粒体","title":"线粒体基质蛋白导入 (p7)","notes":"Protein import into the mitochondrial matrix：前体蛋白N端导肽与TOM受体结合→经接触点→TIM→进入基质→导肽被切除→蛋白折叠。\n\n【本页英文讲解】\n本页讲线粒体基质蛋白（matrix protein）的导入过程。前体蛋白N端的导肽（presequence，即转运信号）先与TOM受体结合，经内外膜接触点，再通过TIM进入基质；随后导肽被切除，蛋白折叠为成熟构象。这是经典的翻译后转运途径。考点：导肽位于N端且可被切除，全过程需分子伴侣辅助折叠并耗能。","page":7,"level":"掌握","img":"assets/img/ch05/p007.jpg","anim":"mito_matrix_import","fig":"蛋白进入线粒体基质的过程：前体蛋白(含导肽)+胞质 Hsp70 → 与 TOM 受体结合 → 经 TOM/TIM23 进入基质 → 基质 Hsp70 结合、ATP 驱动 → 导肽被切除 → 蛋白折叠。图给出“导肽+Hsp70”驱动的完整流程。","points":["前体蛋白N端导肽与TOM受体结合","经内外膜接触点→TIM→进入基质","导肽被切除，蛋白折叠"],"check":{"q":"线粒体基质蛋白的导入过程中，关于其N端导肽的叙述正确的是？","o":["A. 导肽与TOM结合后直接穿过外膜进入基质，不依赖TIM","B. 导肽位于N端，与TOM受体结合后经TIM进入基质并被切除","C. 导肽位于蛋白C端，进入基质后仍保留","D. 导肽位于N端，其切除发生在与TOM受体结合之前"],"a":"B","e":"前体蛋白N端导肽先与TOM受体结合，经内外膜接触点再由TIM进入基质，随后导肽被切除并折叠为成熟构象。","oe":["需经TIM通道进入基质，不能仅靠TOM穿过外膜。","正确描述导肽位置、受体结合及经TIM入基质后被切除。","导肽位于N端而非C端，且入基质后被切除。","导肽在进入基质后才被切除，并非与TOM结合前。"]},"cards":[{"front":"线粒体基质蛋白导入的基本流程是什么？","back":"N端导肽与TOM受体结合→经接触点→TIM→进入基质→导肽被切除→蛋白折叠","mnemonic":"结合、过点、穿TIM、切肽、折叠","type":"流程","useImg":true,"blank":"N端导肽","blank2":"TOM受体"}],"mem":"结合、过点、穿TIM、切肽、折叠","big":"assets/img/ch05/big/p007.jpg","summary":"Protein import into the mitochondrial matrix：前体蛋白N端导肽与TOM受体结合→经接触点→TIM→进入基质→导肽被切除→蛋白折叠","goal":"学完应能掌握并运用「线粒体基质蛋白导入」的核心内容，能解释其机制、比较相关概念。","intuition":"线粒体蛋白导入像“凭票进站”：前体蛋白 N 端的导肽是“车票”，先被外膜的 TOM 识别、经内外膜接触点，再由内膜的 TIM 送进基质；到站后导肽被剪掉，蛋白折叠成形。","experiment":"【体外实验】把带导肽的前体蛋白与分离的线粒体共孵育：前体可被导入而成熟蛋白不能；加蛋白酶处理时，未导入的蛋白被降解，导入后受膜保护的蛋白不被降解——据此证明“导肽引导 + 跨膜导入”。"},{"i":7,"sec":"第一节 线粒体","title":"Hsp70解折叠前体蛋白 (p8)","notes":"运送前，含导肽的蛋白前体(precursor)在细胞质基质中与Hsp70结合，ATP→ADP，解折叠为松散结构(unfolded protein)，才能被导入线粒体。","page":8,"level":"掌握","img":"assets/img/ch05/p008.jpg","anim":null,"fig":"含导肽的前体蛋白在胞质由 Hsp70 结合、维持解析叠；进入线粒体基质后，基质 Hsp70 结合肽链并利用 ATP 拉动其进入；随后导肽被线粒体基质中的蛋白酶切除。图强调 Hsp70 的“分子马达”作用。","points":["运送前前体在细胞质基质中与Hsp70结合，ATP→ADP","解折叠为松散结构后才能被导入线粒体"],"check":{"q":"线粒体前体蛋白被导入前，其在细胞质基质中的变化是？","o":["A. 与Hsp70结合并水解ATP，解折叠为松散结构","B. 与Hsp70结合后折叠得更紧密","C. Hsp70使其磷酸化后进入线粒体","D. 前体蛋白无需解折叠即可直接导入"],"a":"A","e":"运送前含导肽的蛋白前体在细胞质基质中与Hsp70结合，ATP水解为ADP，解折叠为松散结构（unfolded protein）才能被导入线粒体。","oe":["正确，Hsp70结合并水解ATP使前体解折叠。","前体需解析叠而非更紧密折叠，故错误。","Hsp70不使其磷酸化，机制是解折叠。","前体须解析叠后才能跨膜导入，故错误。"]},"cards":[{"front":"运送前，含导肽的前体蛋白在胞质中如何被解折叠？","back":"与Hsp70结合；ATP→ADP供能；解折叠为松散结构后才能被导入线粒体","mnemonic":"Hsp70松绑，ATP买单","type":"流程","useImg":false,"blank":"Hsp70","blank2":"ATP→ADP供能"}],"mem":"Hsp70松绑，ATP买单","big":"assets/img/ch05/big/p008.jpg","terms":[{"t":"蛋白前体","en":"precursor","d":"含N端导肽、尚未切除信号的未成熟蛋白。"},{"t":"去折叠蛋白","en":"unfolded protein","d":"在分子伴侣帮助下解析叠成松散结构的蛋白；只有去折叠的蛋白才能被导入线粒体。"}],"summary":"运送前，含导肽的蛋白前体(precursor)在细胞质基质中与Hsp70结合，ATP→ADP，解折叠为松散结构(unfolded protein)，才能被导入线粒体","goal":"学完应能掌握并运用「Hsp70解折叠前体蛋白」的核心内容，能解释其机制、比较相关概念。","intuition":"进线粒体前，蛋白像“要被塞进窄门的家具”：必须先拆开（去折叠）。胞质 Hsp70 结合前体并耗 ATP 把它拉松，才能穿过膜的窄通道；进基质后再由基质 Hsp70 帮忙重新折叠。"},{"i":8,"sec":"第一节 叶绿体","title":"叶绿体蛋白的转运肽 (p9)","notes":"细胞质基质游离核糖体中合成的叶绿体前体蛋白，N端含一个额外的氨基酸序列，称转运肽(transit peptides)。转运肽引导蛋白进入叶绿体后被切除。","page":9,"level":"掌握","img":"assets/img/ch05/p009.jpg","anim":null,"fig":null,"points":["叶绿体前体蛋白N端含一个额外的氨基酸序列，即转运肽","转运肽引导蛋白进入叶绿体后被切除"],"check":{"q":"关于叶绿体前体蛋白的转运肽（transit peptides），正确的是？","o":["A. 位于N端，引导蛋白进入叶绿体后被切除","B. 位于C端，进入叶绿体后保留","C. 由叶绿体基因编码","D. 仅存在于叶绿体基质蛋白中"],"a":"A","e":"细胞质游离核糖体合成的叶绿体前体蛋白N端含额外的转运肽，引导蛋白进入叶绿体后被切除。","oe":["正确，N端转运肽引导入叶绿体后被切除。","转运肽位于N端且进入后被切除，故错误。","前体蛋白由核基因编码，非叶绿体基因。","多种叶绿体蛋白均含转运肽，非仅基质蛋白。"]},"cards":[{"front":"叶绿体前体蛋白的N端有什么特殊序列？其功能是什么？","back":"转运肽(transit peptide)；引导蛋白进入叶绿体后被切除","mnemonic":"转运肽=进叶绿体的'门票'，进门即撕","type":"定义","useImg":false,"blank":"转运肽","blank2":"叶绿体"}],"mem":"转运肽=进叶绿体的'门票'，进门即撕","big":"assets/img/ch05/big/p009.jpg","terms":[{"t":"转运肽","en":"transit peptide","d":"叶绿体前体蛋白N端的一段额外序列，引导蛋白进入叶绿体后被切除。"}],"summary":"细胞质基质游离核糖体中合成的叶绿体前体蛋白，N端含一个额外的氨基酸序列，称转运肽(transit peptides)","goal":"学完应能掌握并运用「叶绿体蛋白的转运肽」的核心内容，能解释其机制、比较相关概念。","intuition":"叶绿体蛋白的“地址”叫转运肽：位于前体 N 端，把它领进叶绿体后就被切掉。"},{"i":9,"sec":"第一节 叶绿体","title":"叶绿体蛋白的分选 (p10)","notes":"叶绿体蛋白的分选：①叶绿体基质蛋白的导入和转运肽的切割；②类囊体腔蛋白的导入和转运肽的切除；③类囊体膜蛋白的导入。展示叶绿体蛋白的多层次分选。","page":10,"level":"掌握","img":"assets/img/ch05/p010.jpg","anim":"chloroplast_import","fig":null,"points":["叶绿体基质蛋白的导入与转运肽切割","类囊体腔蛋白的导入与转运肽切除","体现叶绿体蛋白的多层次分选"],"check":{"q":"叶绿体蛋白的分选具有多层次性，下列哪项符合其分选途径？","o":["A. 类囊体膜蛋白不需转运肽引导即可插入","B. 叶绿体基质蛋白导入后其转运肽被切除","C. 类囊体腔蛋白的转运肽被切割后即停止，不再跨膜","D. 叶绿体蛋白只能分选到叶绿体基质一个部位"],"a":"B","e":"叶绿体蛋白分选具有多层次性，可分别导入基质、类囊体腔和类囊体膜，相应的转运肽被切除。","oe":["类囊体膜蛋白也依赖转运肽进行定向导入。","基质蛋白导入叶绿体基质后转运肽被切割去除。","类囊体腔蛋白需进一步跨类囊体膜并切除转运肽。","叶绿体蛋白可分别分选至基质、类囊体腔和类囊体膜。"]},"cards":[{"front":"叶绿体蛋白分选有哪三个层次？","back":"①基质蛋白导入+转运肽切割；②类囊体腔蛋白导入+转运肽切除；③类囊体膜蛋白导入","mnemonic":"基质→腔→膜，三层递进","type":"流程","useImg":true,"blank":"基质蛋白导入","blank2":"类囊体腔蛋白导入"}],"mem":"基质→腔→膜，三层递进","big":"assets/img/ch05/big/p010.jpg","summary":"叶绿体蛋白的分选：①叶绿体基质蛋白的导入和转运肽的切割；②类囊体腔蛋白的导入和转运肽的切除；③类囊体膜蛋白的导入","goal":"学完应能掌握并运用「叶绿体蛋白的分选」的核心内容，能解释其机制、比较相关概念。","intuition":"叶绿体蛋白像“要分到不同车间的工人”：基质蛋白、类囊体腔蛋白、类囊体膜蛋白各有不同靶向，分层送达。"},{"i":10,"sec":"第一节 叶绿体","title":"类囊体腔蛋白的双区转运肽 (p11)","notes":"定位于叶绿体类囊体腔中的蛋白质，其前体蛋白N端的转运肽可分2个区：①N端含导向叶绿体基质序列；②接下来是导向类囊体腔(thylakoid)的序列。分两步引导。","page":11,"level":"掌握","img":"assets/img/ch05/p011.jpg","anim":null,"fig":"定位到叶绿体类囊体腔的蛋白：其转运肽可分两个区——N 端导向叶绿体基质序列 + 导向类囊体腔序列。蛋白先进入基质，切除第一段，再经类囊体膜进入腔，切除第二段。图说明“两段信号、两步引导”。","points":["类囊体腔蛋白的转运肽可分2个区","N端含导向叶绿体基质序列，其后为导向类囊体腔序列","分两步引导"],"check":{"q":"定位于叶绿体类囊体腔的蛋白质，其转运肽的特点是？","o":["A. 只含一段导向细胞质的序列","B. 位于蛋白C端且不可切除","C. 分为两区：N端导向基质序列和导向类囊体腔序列","D. 直接导向线粒体基质"],"a":"C","e":"该类蛋白前体N端转运肽分两区，先导向叶绿体基质，再导向类囊体腔，分两步引导并逐段切除。","oe":["错：需导向基质与类囊体腔两段，不符合本页所学概念","错：转运肽位于N端并被切除，不符合本页所学概念","对：符合“两段信号、两步引导”","错：定位叶绿体而非线粒体，不符合本页所学概念"],"basis":"N端含导向叶绿体基质序列；接下来是导向类囊体腔的序列"},"cards":[{"front":"类囊体腔蛋白的转运肽为何称'双区转运肽'？","back":"N端含两区：①导向叶绿体基质序列；②导向类囊体腔序列；分两步引导","mnemonic":"两段票：先到基质，再转腔","type":"组成","useImg":true,"blank":"导向叶绿体基质序列","blank2":"导向类囊体腔序列"}],"mem":"两段票：先到基质，再转腔","big":"assets/img/ch05/big/p011.jpg","terms":[{"t":"类囊体","en":"thylakoid","d":"叶绿体内部由膜围成的扁平囊，类囊体腔是其内部空间。"}],"summary":"定位于叶绿体类囊体腔中的蛋白质，其前体蛋白N端的转运肽可分2个区：①N端含导向叶绿体基质序列；②接下来是导向类囊体腔(thylakoid)的序列","goal":"学完应能掌握并运用「类囊体腔蛋白的双区转运肽」的核心内容，能解释其机制、比较相关概念。","intuition":"类囊体腔蛋白的转运肽分两段，像“先到小区、再到楼栋”：第一段导向叶绿体基质，第二段再导向类囊体腔。"},{"i":11,"sec":"第一节 叶绿体","title":"叶绿体基质蛋白 (p12)","notes":"定位于叶绿体基质(stroma)中的蛋白(eg. Rubisco，CO2固定的重要酶类，其中的8个小亚基由核基因编码，翻译后转运)。转运肽被切除后蛋白折叠成活性形式。","page":12,"level":"掌握","img":"assets/img/ch05/p012.jpg","anim":null,"fig":"定位于叶绿体基质的蛋白(如 Rubisco 小亚基)：前体由 N 端转运肽引导，穿过叶绿体双层膜进入基质，转运肽被基质中的蛋白酶切除，成为成熟蛋白。Rubisco 是光合作用固定 CO₂ 的关键酶。","points":["Rubisco 8个小亚基由核基因编码，翻译后转运进入叶绿体基质","转运肽被切除后蛋白折叠成活性形式"],"check":{"q":"关于叶绿体基质蛋白（如Rubisco小亚基），正确的是？","o":["A. 由叶绿体基因编码并在基质内合成","B. 不需要转运肽即可进入基质","C. 转运肽切除后蛋白立即降解","D. 由核基因编码、翻译后转运，转运肽切除后折叠成活性形式"],"a":"D","e":"叶绿体基质蛋白（如Rubisco小亚基）由核基因编码、翻译后转运；转运肽被切除后蛋白折叠成活性形式。","oe":["Rubisco小亚基由核基因编码，非叶绿体基因。","进入基质依赖转运肽引导，故错误。","转运肽切除后蛋白折叠成活性形式而非降解。","正确，核基因编码、转运肽切除后折叠成活性形式。"]},"cards":[{"front":"Rubisco小亚基由什么编码？如何定位到叶绿体基质？","back":"核基因编码；在胞质核糖体合成后翻译后转运入基质，转运肽切除后折叠成活性形式","mnemonic":"小亚基核编码，进基质再组装","type":"例证","useImg":false,"blank":"核基因编码","blank2":"胞质核糖体"}],"mem":"小亚基核编码，进基质再组装","big":"assets/img/ch05/big/p012.jpg","terms":[{"t":"叶绿体基质","en":"stroma","d":"叶绿体被膜以内、类囊体以外的空间，含Rubisco等酶。"}],"summary":"定位于叶绿体基质(stroma)中的蛋白(eg. Rubisco，CO2固定的重要酶类，其中的8个小亚基由核基因编码，翻译后转运)","goal":"学完应能掌握并运用「叶绿体基质蛋白」的核心内容，能解释其机制、比较相关概念。","intuition":"Rubisco 小亚基是典型例子：核基因编码、胞质合成后运进叶绿体基质，切掉转运肽后折叠成有活性的酶。"}],"mcq":[{"id":"ch05_mcq_1","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体蛋白N端的引导序列称为？","o":["A. 信号肽","B. 导肽(presequence)","C. 转运肽","D. 前导序列"],"a":"B","e":"线粒体蛋白N端为导肽(presequence)；叶绿体蛋白N端为转运肽(transit peptide)。两者都是翻译后转移的引导信号。","kp":"ch05_s0_2","oe":["信号肽通常指引导分泌蛋白进入内质网的序列，非线粒体。","线粒体蛋白N端的引导序列称为导肽（presequence）。","转运肽指叶绿体蛋白N端的引导序列，非线粒体。","前导序列是泛指名称，线粒体引导序列标准称导肽。"]},{"id":"ch05_mcq_2","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体蛋白前体进入基质需要？","o":["A. 保持折叠状态","B. 由Hsp70帮助解折叠","C. 直接穿过膜","D. 经核孔"],"a":"B","e":"Only unfolded proteins can be imported——前体蛋白在胞质与Hsp70结合，ATP水解后解折叠，才能经TOM/TIM进入线粒体。","kp":"ch05_s0_2","oe":["错误。前体必须解折叠才可被导入，保持折叠无法通过TOM/TIM。","正确。胞质Hsp70结合前体并水解ATP，使其解折叠后经TOM/TIM进入基质。","错误。需借助TOM/TIM转运复合体，不能直接穿过线粒体膜。","错误。核孔是核质运输通道，线粒体蛋白不经核孔进入基质。"]},{"id":"ch05_mcq_3","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体蛋白前体跨膜转运发生在？","o":["A. 任意膜位置","B. 内外膜接触点","C. 核孔","D. 高尔基体"],"a":"B","e":"前体蛋白到线粒体基质的转移只发生在少数线粒体内外膜相'接触点'，经TOM(外膜)和TIM(内膜)复合体。","kp":"ch05_s0_2","oe":["错误。并非任意膜位置，只在少数内外膜接触点进行转运。","正确。前体经内外膜接触点的TOM与TIM复合体转运进入基质。","错误。核孔介导核质运输，与线粒体蛋白跨膜转运无关。","错误。高尔基体参与膜泡运输，不参与线粒体蛋白导入。"]},{"id":"ch05_mcq_4","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"叶绿体蛋白N端的引导序列称为？","o":["A. 导肽","B. 转运肽(transit peptide)","C. 信号肽","D. NLS"],"a":"B","e":"叶绿体前体蛋白N端含转运肽(transit peptide)，引导入叶绿体后被切除。","kp":"ch05_s0_8","oe":["错误。导肽多指线粒体蛋白引导序列，叶绿体特称转运肽。","正确。叶绿体前体蛋白N端为转运肽，引导入叶绿体后被切除。","错误。信号肽引导蛋白进入内质网，属共翻译转运。","错误。NLS是核定位信号，负责引导蛋白进入细胞核。"]},{"id":"ch05_mcq_5","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"类囊体腔蛋白的转运肽特点是？","o":["A. 只有一段","B. 分2个区(导向基质+导向类囊体腔)","C. 无引导功能","D. 位于C端"],"a":"B","e":"类囊体腔蛋白的转运肽分2区：N端导向叶绿体基质序列，接下来是导向类囊体腔的序列，分两步引导。","kp":"ch05_s0_10","oe":["错误。并非只有一段，而是分导向基质与类囊体腔两个区。","正确。转运肽分两区，先导向叶绿体基质，再导向类囊体腔。","错误。转运肽具有引导功能，可定向运输蛋白至类囊体腔。","错误。转运肽位于蛋白N端，而不是C端。"]},{"id":"ch05_mcq_6","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"核孔复合体(NPC)的直径(通道)约为？","o":["A. 9-10nm","B. 120nm","C. 1nm","D. 50nm"],"a":"A","e":"NPC通道直径约9-10nm，外径约120nm；40~60kDa以下小分子可自由扩散。","kp":"ch05_s0_4","oe":["正确。NPC通道直径约9-10nm，小分子物质可自由扩散通过。","错误。120nm是核孔复合体的外径，不是其通道直径。","错误。1nm过小，远小于实际通道，多数分子无法通过。","错误。50nm大于实际通道直径，与事实不符。"]},{"id":"ch05_mcq_7","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"引导蛋白质进入细胞核的信号是？","o":["A. NLS(核定位信号)","B. NES","C. KDEL","D. M6P"],"a":"A","e":"NLS(核定位信号)引导亲核蛋白入核；NES(核输出信号)介导出核；KDEL是ER驻留信号；M6P是溶酶体信号。","kp":"ch05_s0_8","oe":["正确。NLS核定位信号引导亲核蛋白经NPC进入细胞核。","错误。NES是核输出信号，介导核内蛋白输出到细胞质。","错误。KDEL是内质网驻留信号，使蛋白滞留于内质网。","错误。M6P是溶酶体酶的分选信号，导向溶酶体。"]},{"id":"ch05_mcq_8","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"识别并结合NLS的胞质受体是？","o":["A. importin(输入蛋白)","B. exportin","C. SRP","D. dynamin"],"a":"A","e":"亲核蛋白必须与NLS受体importin结合才能穿过NPC。importin分布在胞质溶胶中。","kp":"ch05_s0_2","oe":["正确。胞质中importin识别并结合NLS，介导货物蛋白入核。","错误。exportin介导含NES的货物蛋白从核内输出。","错误。SRP识别信号肽，介导分泌蛋白的共翻译转运。","错误。dynamin是参与膜泡颈缩的GTP酶，与入核无关。"]},{"id":"ch05_mcq_9","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"调控核质运输的关键GTP酶是？","o":["A. Ran","B. Rab","C. Sar","D. ARF"],"a":"A","e":"Ran是核质运输的关键GTP酶。Ran-GTP(主要在核内)结合importin使其释放货物蛋白。","kp":"ch05_s0_1","oe":["正确。Ran是核质运输的关键GTP酶，Ran-GTP调控货物释放。","错误。Rab调控膜泡运输与融合，不参与核质运输。","错误。Sar参与内质网到高尔基体的膜泡形成。","错误。ARF参与膜泡形成与囊泡运输，非核质运输。"]},{"id":"ch05_mcq_10","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"40~60kDa以下的小分子出入细胞核的方式是？","o":["A. 主动运输","B. 被动扩散(经NPC)","C. 胞吞","D. 跨膜转运"],"a":"B","e":"NPC双功能：离子、小分子代谢产物、40~60kDa以下小分子可自由扩散出入核；大分子经NLS/NES主动运输。","kp":"ch05_s0_0","oe":["错误。小分子经NPC自由扩散，不属消耗能量的主动运输。","正确。40~60kDa以下小分子可经NPC自由扩散出入细胞核。","错误。胞吞是大分子物质入胞方式，并不是入核方式。","错误。经核孔扩散进入，而非跨脂双层膜的跨膜转运。"]},{"id":"ch05_mcq_11","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体外膜和内膜的蛋白转运子分别是？","o":["A. TOM和TIM","B. TIM和TOM","C. SRP和SR","D. NPC"],"a":"A","e":"外膜转运子TOM复合体、内膜转运子TIM复合体，前体蛋白经TOM进入、经TIM进入基质。","kp":"ch05_s0_4","oe":["正确。外膜转运子为TOM复合体，内膜转运子为TIM复合体。","错误。顺序颠倒，外膜是TOM，内膜是TIM。","错误。SRP与SR参与内质网共翻译转运，与线粒体无关。","错误。NPC是核孔复合体，负责核质之间的运输。"]},{"id":"ch05_mcq_12","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"过氧化物酶体的另一种名称是？","o":["A. 微体(microbody)","B. 溶酶体","C. 内体","D. 液泡"],"a":"A","e":"过氧化物酶体又称微体(microbody)，单层膜，含氧化酶和过氧化氢酶。","kp":"ch05_s0_0","oe":["正确。过氧化物酶体又称微体，为单层膜细胞器。","错误。溶酶体含酸性水解酶，与过氧化物酶体不同。","错误。内体参与胞吞物质的分选，不是过氧化物酶体。","错误。液泡是植物细胞的贮水细胞器，另属一类。"]}],"judge":[{"id":"ch05_judge_1","modI":0,"q":"线粒体蛋白N端含导肽，叶绿体蛋白N端含转运肽。","a":"对","e":"线粒体蛋白N端为导肽(presequence)，叶绿体蛋白N端为转运肽(transit peptide)。","kp":"ch05_s0_8","oe":["线粒体蛋白N端为导肽，叶绿体蛋白N端为转运肽。","误把线粒体与叶绿体的N端信号名称互换，故判错。"]},{"id":"ch05_judge_2","modI":0,"q":"线粒体蛋白前体必须解折叠后才能被导入线粒体。","a":"对","e":"只有解折叠的蛋白能进入线粒体；前体蛋白在胞质由Hsp70帮助、消耗ATP解折叠。","kp":"ch05_s0_7","oe":["只有解折叠的蛋白能进入线粒体，前体蛋白在胞质由Hsp70耗能解折叠。","误以为折叠态蛋白可直接导入或无需分子伴侣，故判错。"]},{"id":"ch05_judge_3","modI":0,"q":"线粒体外膜和内膜的蛋白转运子分别是TOM和TIM复合体。","a":"对","e":"外膜为TOM复合体、内膜为TIM复合体，前体蛋白经二者进入基质。","kp":"ch05_s0_4","oe":["线粒体外膜为TOM复合体、内膜为TIM复合体，前体蛋白经二者进入基质。","误把TOM与TIM对应的膜或内外顺序记反，故判错。"]},{"id":"ch05_judge_10","modI":0,"q":"叶绿体类囊体腔蛋白的转运肽可分为导向基质和导向类囊体腔两个区。","a":"对","e":"类囊体腔蛋白转运肽分2区：N端导向基质序列+导向类囊体腔序列，分两步引导。","kp":"ch05_s0_10","oe":["类囊体腔蛋白转运肽分N端导向基质区与导向类囊体腔区，分两步引导。","误判为错者多不知转运肽可分导向基质和类囊体腔两个功能区。"]}],"fill":[{"id":"ch05_fill_1","modI":0,"q":"线粒体蛋白N端含________,叶绿体蛋白N端含________,两者都引导翻译后转移。","a":"导肽(presequence),转运肽(transit peptide)","kp":"ch05_s0_8","oe":["线粒体蛋白前体N端的导肽引导其翻译后转运入线粒体。","叶绿体蛋白N端的转运肽引导其翻译后转运入叶绿体。"]},{"id":"ch05_fill_2","modI":0,"q":"线粒体蛋白前体在胞质由________帮助、消耗________解折叠后才能导入。","a":"Hsp70,ATP","kp":"ch05_s0_7","oe":["胞质Hsp70分子伴侣使前体解折叠并保持可转运状态。","前体解折叠由Hsp70消耗ATP驱动，导入过程也需ATP。"]},{"id":"ch05_fill_3","modI":0,"q":"线粒体外膜转运子为________复合体,内膜为________复合体,前体在内外膜________点转运。","a":"TOM,TIM,接触","kp":"ch05_s0_4","oe":["线粒体外膜转运子为TOM复合体，识别并导入前体蛋白。","线粒体内膜转运子为TIM复合体，将前体送入基质。","前体在内外膜相互接触的接触点处协调转运，故填接触点。"]},{"id":"ch05_fill_8","modI":0,"q":"Rubisco的小亚基由________基因编码,翻译后转运入叶绿体________。","a":"核,基质","kp":"ch05_s0_11","oe":["Rubisco小亚基由核基因编码，大亚基由叶绿体基因编码。","小亚基在胞质合成后经转运肽导入叶绿体基质，再与rbcL大亚基装配。"]},{"id":"ch05_fill_11","modI":0,"q":"类囊体腔蛋白的转运肽分2区:________序列和导向________的序列。","a":"导向叶绿体基质,类囊体腔","kp":"ch05_s0_10","oe":["转运肽第一区引导蛋白进入叶绿体基质，故填导向叶绿体基质。","第二区引导蛋白由基质进一步进入类囊体腔，故填类囊体腔。"]}],"short":[{"id":"ch05_short_1","modI":0,"q":"简述线粒体蛋白质翻译后转运的过程。","a":"线粒体蛋白质的翻译后转运：\n\n【特点】\n线粒体绝大多数蛋白由核基因编码，在胞质游离核糖体合成后转运。\n\n【过程】\n①在细胞质基质中，含N端导肽(presequence)的前体蛋白与Hsp70结合，ATP→ADP，解折叠为松散结构；\n②前体蛋白的导肽与线粒体外膜受体识别；\n③在内外膜接触点，经外膜转运子TOM复合体进入；\n④经内膜转运子TIM复合体进入基质；\n⑤导肽被切除，蛋白在基质中重新折叠成活性形式；\n⑥部分蛋白进一步分选到内膜、膜间隙或外膜。\n\n【要点】\n①需N端导肽；②必须解折叠才能导入；③发生在内外膜接触点；④消耗能量(ATP)。\n\n【对比】叶绿体蛋白用转运肽(transit peptide)引导。","kp":"ch05_s0_1"},{"id":"ch05_short_3","modI":0,"q":"比较线粒体、叶绿体、过氧化物酶体蛋白的翻译后转运。","a":"三种细胞器蛋白翻译后转运的比较：\n\n| 细胞器 | 引导信号 | 转运子/受体 | 特点 |\n|---|---|---|---|\n| 线粒体 | N端导肽(presequence) | TOM/TIM复合体 | 在内外膜接触点转运，需解折叠 |\n| 叶绿体 | N端转运肽(transit peptide) | TOC/TIC复合体 | 转运肽分2区(基质+类囊体腔) |\n| 过氧化物酶体 | PTS1/PTS2 | Pex蛋白 | 可折叠后导入，有两种发生途径 |\n\n【共同点】\n①蛋白由核基因编码、胞质游离核糖体合成；\n②翻译后转运；\n③依赖N端信号序列；\n④信号序列被切除；\n⑤消耗能量。\n\n【不同点】\n①线粒体需完全解折叠(Hsp70)，过氧化物酶体可折叠导入；\n②叶绿体转运肽分两区，可进入基质和类囊体腔；\n③过氧化物酶体还有ER出芽从头形成途径。\n\n【意义】保证细胞器蛋白正确定位。","kp":"ch05_s0_8"},{"id":"ch05_short_5","modI":0,"q":"简述叶绿体蛋白质的分选途径。","a":"叶绿体蛋白质的分选：\n\n【共同起点】\n细胞质游离核糖体中合成的前体蛋白N端含转运肽(transit peptide)。\n\n【分选途径】\n①叶绿体基质蛋白：转运肽引导经TOC/TIC进入基质→转运肽被切割→折叠成活性蛋白(如Rubisco小亚基)。\n②类囊体腔蛋白：转运肽分2区——N端导向叶绿体基质序列+接下来导向类囊体腔序列→先进入基质，再经类囊体膜进入腔→切除转运肽。\n③类囊体膜蛋白：转运肽引导到类囊体膜并整合。\n\n【特点】\n①转运肽分2区，可两步引导；\n②转运肽最终被切除；\n③部分蛋白需叶绿体自身蛋白(如cpSecA)协助。\n\n【意义】\n保证叶绿体各亚区室蛋白的正确定位，是叶绿体功能的基础。","kp":"ch05_s0_9"}],"calc":[{"id":"ch05_calc_1","modI":0,"q":"论述蛋白质翻译后转运的主要途径及分子机制。","a":"翻译后转运将胞质合成的蛋白运往线粒体/叶绿体/过氧化物酶体/细胞核,机制各异","steps":"【定义】\n蛋白质在细胞质游离核糖体完全合成后，再转运至特定细胞器。\n\n【1. 线粒体蛋白转运】\n①N端导肽；②Hsp70+ATP解折叠；③内外膜接触点经TOM/TIM；④导肽切除、重折叠。\n\n【2. 叶绿体蛋白转运】\n①N端转运肽(分2区)；②经TOC/TIC；③分选到基质/类囊体腔/膜；④转运肽切除。\n\n【3. 过氧化物酶体蛋白转运】\n①PTS1/PTS2信号；②Pex受体；③可折叠导入；④两种发生途径(ER出芽/分裂)。\n\n【4. 核孔运输】\n①NLS/NES信号；②importin/exportin受体；③经NPC；④Ran-GTP调控。\n\n【共同点】\n①蛋白由核基因编码、胞质合成；②翻译后转运；③依赖信号序列；④信号被切除(部分)；⑤消耗能量。\n\n【意义】\n保证细胞器蛋白正确定位，维持细胞区室化功能。","kp":"ch05_s0_0"},{"id":"ch05_calc_3","modI":0,"q":"论述细胞器蛋白靶向信号(分选信号)的多样性及其意义。","a":"不同细胞器使用不同的靶向信号,构成蛋白质分选的'邮政编码'系统","steps":"【各类靶向信号】\n①信号肽(signal peptide)：N端引导蛋白入ER(共翻译转移)；\n②导肽(presequence)：N端引导线粒体蛋白；\n③转运肽(transit peptide)：N端引导叶绿体蛋白(分2区)；\n④PTS1/PTS2：过氧化物酶体蛋白；\n⑤NLS：核定位信号(入核)；\n⑥NES：核输出信号(出核)；\n⑦KDEL：ER驻留/回收信号；\n⑧M6P：溶酶体酶分选信号。\n\n【共同特点】\n①都是特定的氨基酸序列(或糖基修饰)；\n②被特异受体识别；\n③部分在完成任务后被切除；\n④引导蛋白到达正确部位。\n\n【意义】\n①是蛋白质分选的分子基础('邮政编码')；\n②保证细胞区室化、各细胞器功能正常；\n③信号异常导致疾病(如家族性高胆固醇血症、I细胞病、囊性纤维化等)；\n④是基因工程中蛋白定位改造的基础。","kp":"ch05_s0_9"}],"term":[{"id":"ch05_term_1","modI":0,"term":"导肽(Presequence)","def":"①线粒体蛋白N端的引导序列（定义）。②功能：引导前体蛋白进入线粒体，与膜受体识别（功能）。③特点：完成使命后被切除（特点）。④与叶绿体的转运肽(transit peptide)相对应（对比）。","kps":"踩分点:①定义(1分)②功能(1分)③切除(1分)④与转运肽对比(1分)","kp":"ch05_s0_2"},{"id":"ch05_term_2","modI":0,"term":"转运肽(Transit Peptide)","def":"①叶绿体前体蛋白N端的引导序列（定义）。②特点：可分2区(导向叶绿体基质+导向类囊体腔)，完成使命后被切除（特点）。③功能：引导叶绿体蛋白分选到基质、类囊体腔或膜（功能）。","kps":"踩分点:①定义(1分)②分2区(1分)③切除(1分)④功能(1分)","kp":"ch05_s0_8"},{"id":"ch05_term_8","modI":0,"term":"TOM/TIM复合体","def":"①线粒体外膜(TOM)和内膜(TIM)的蛋白转运子复合体（定义）。②功能：前体蛋白经TOM进入、经TIM进入线粒体基质（功能）。③位置：在内外膜接触点协同工作（位置）。","kps":"踩分点:①定义(1分)②功能(2分)③位置(1分)","kp":"ch05_s0_4"},{"id":"ch05_term_10","modI":0,"term":"分子伴侣Hsp70在线粒体蛋白转运中的作用","def":"①Hsp70在胞质中与前体蛋白结合（定义）。②功能：消耗ATP使前体蛋白解折叠为松散结构，才能被导入线粒体（功能）。③意义：线粒体只允许解折叠蛋白进入（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch05_s0_7"},{"id":"ch05_term_11","modI":0,"term":"共翻译转移与翻译后转移","def":"①共翻译转移：蛋白边合成边经信号肽引导入ER(分泌蛋白、膜蛋白、溶酶体酶)（定义）。②翻译后转移：蛋白在游离核糖体完全合成后转运至线粒体、叶绿体、过氧化物酶体、细胞核（定义）。③区别：转移时间不同、信号序列不同、受体不同（区别）。","kps":"踩分点:①共翻译(1分)②翻译后(1分)③区别(2分)","kp":"ch05_s0_0"},{"id":"ch05_term_14","modI":0,"term":"接触点(Contact Site)","def":"①线粒体内外膜靠近的区域（定义）。②功能：前体蛋白在此经TOM/TIM转运到线粒体基质（功能）。③意义：是线粒体蛋白导入的关键位点（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch05_s0_3"},{"id":"ch05_term_15","modI":0,"term":"细胞器蛋白靶向信号","def":"①引导蛋白质到达特定细胞器的氨基酸序列（定义）。②种类：信号肽(ER)、导肽(线粒体)、转运肽(叶绿体)、PTS(过氧化物酶体)、NLS/NES(核)、KDEL(ER驻留)、M6P(溶酶体)（种类）。③意义：是蛋白质分选的'邮政编码'，信号异常导致疾病（意义）。","kps":"踩分点:①定义(1分)②种类(2分)③意义(1分)","kp":"ch05_s0_7"}]},{"i":1,"name":"模块二：核孔运输","slides":[{"i":0,"sec":"第二节 细胞核","title":"细胞核结构 (p13)","notes":"细胞核：核被膜、染色质/染色体(DNA)、核仁(nucleolus)。核被膜为双层核膜，上有核孔复合体(nuclear pore complex, NPC)。核质运输是后翻译转运的重要途径。","page":13,"level":"掌握","img":"assets/img/ch05/p013.jpg","anim":"nucleus_structure","fig":"细胞核的结构：核被膜(双层膜)、核孔复合体、染色质/染色体、核仁、核基质。核被膜将核与胞质分开，核孔复合体是物质交换的通道。图给出细胞核各组成部分的层次关系。","points":["细胞核：核被膜、染色质/染色体、核仁","核被膜为双层核膜，上有核孔复合体(NPC)"],"check":{"q":"关于细胞核的结构，正确的是？","o":["A. 核被膜为单层膜，上无核孔","B. 核被膜为双层核膜，上有核孔复合体","C. 细胞核由核膜、核糖体、中心体组成","D. 核仁是DNA复制场所"],"a":"B","e":"细胞核包括核被膜、染色质/染色体（DNA）和核仁；核被膜为双层核膜，上有核孔复合体，核质运输是后翻译转运的重要途径。","oe":["核被膜为双层膜且有核孔复合体，故错误。","正确，核被膜为双层膜并具核孔复合体。","核糖体与中心体非细胞核结构，故错误。","核仁与核糖体形成有关，非DNA复制场所。"]},"cards":[{"front":"细胞核由哪三部分组成？核被膜的结构特点是什么？","back":"核被膜、染色质/染色体、核仁；核被膜为双层核膜，上有核孔复合体(NPC)","mnemonic":"核三件套：膜、质、仁","type":"组成","useImg":true,"blank":"核孔复合体","blank2":"核被膜"}],"mem":"核三件套：膜、质、仁","big":"assets/img/ch05/big/p013.jpg","summary":"细胞核：核被膜、染色质/染色体(DNA)、核仁(nucleolus)","goal":"学完应能掌握并运用「细胞核结构」的核心内容，能解释其机制、比较相关概念。","intuition":"核像一个“带闸门的管理中心”：双层核膜上有核孔复合体，里面装 DNA（染色质）和核仁。"},{"i":1,"sec":"第二节 细胞核","title":"胰腺细胞核电镜 (p14)","notes":"胰腺细胞核电镜图：显示核仁(Nu)、核孔复合体(NPC)、染色质(Chr)和核被膜(NE)。核孔复合体位于核被膜上，是核质物质交换的通道。","page":14,"level":"理解","img":"assets/img/ch05/p014.jpg","anim":null,"fig":null,"points":["电镜图显示核仁、核孔复合体、染色质、核被膜","核孔复合体是核质物质交换的通道"],"check":{"q":"胰腺细胞核电镜图中，核孔复合体(NPC)的主要功能是？","o":["A. 维持染色质的螺旋结构","B. 合成核糖体RNA","C. 作为核质物质交换的通道","D. 储存遗传物质DNA"],"a":"C","e":"电镜图中核孔复合体(NPC)位于核被膜上，是核质之间进行物质交换的通道。","oe":["染色质包装与组蛋白等有关，与NPC无关。","rRNA在核仁合成，不是核孔复合体的功能。","核孔复合体是核质间物质交换的通道。","DNA储存于核内染色质，NPC不承担储存。"]},"cards":null,"mem":"核电镜：核仁、核孔复合体、染色质、核被膜","big":"assets/img/ch05/big/p014.jpg","summary":"胰腺细胞核电镜图：显示核仁(Nu)、核孔复合体(NPC)、染色质(Chr)和核被膜(NE)","goal":"学完应能理解并说明「胰腺细胞核电镜」。"},{"i":2,"sec":"第二节 细胞核","title":"核孔复合体(NPC) (p15)","notes":"核孔复合体(nuclear pore complex, NPC)：所有真核细胞(酵母、人)间期细胞核普遍存在。核孔的直径为9-10nm(通道)、外径约120nm。是核质物质交换的双向通道。","page":15,"level":"掌握","img":"assets/img/ch05/p015.jpg","anim":"npc_structure","fig":null,"points":["所有真核细胞间期细胞核普遍存在NPC","核孔通道直径9–10nm、外径约120nm","是核质物质交换的双向通道"],"check":{"q":"关于核孔复合体（NPC），下列叙述正确的是？","o":["A. 所有真核细胞间期核普遍存在，核孔通道直径9-10nm","B. 仅高等动物细胞才有，直径约120nm的通道","C. 是单向出核通道，不许物质入核","D. 位于核膜内侧，由单层膜构成"],"a":"A","e":"核孔复合体在所有真核细胞间期细胞核普遍存在，核孔通道直径9-10nm、外径约120nm，是核质物质交换的双向通道。","oe":["正确，普遍存在且通道直径9-10nm。","酵母到人均有NPC，且120nm为外径非通道。","NPC是双向通道，入核出核均可，故错误。","NPC是核膜上的孔道结构，非单层膜构成。"]},"cards":[{"front":"核孔复合体(NPC)的通道直径和外径分别是多少？","back":"通道直径9-10nm；外径约120nm","type":"组成数字","useImg":true,"blank":"通道直径9-10nm","blank2":"外径约120nm"},{"front":"NPC的功能是什么？存在于哪些细胞？","back":"核质物质交换的双向通道；所有真核细胞间期核普遍存在","mnemonic":"NPC=核质双向大门","type":"功能","useImg":false,"blank":"核质物质交换的双向通道","blank2":"真核细胞间期核"}],"mem":"NPC=核质双向大门","big":"assets/img/ch05/big/p015.jpg","summary":"核孔复合体(nuclear pore complex, NPC)：所有真核细胞(酵母、人)间期细胞核普遍存在","goal":"学完应能掌握并运用「核孔复合体(NPC)」的核心内容，能解释其机制、比较相关概念。","intuition":"核孔复合体像“核膜上的智能闸门”：小分子可自由扩散通过，大分子要凭 NLS/NES“通行证”、耗能主动进出。"},{"i":3,"sec":"第二节 细胞核","title":"NPC电镜观察 (p16-17)","notes":"用冷冻蚀刻电镜技术和高分辨率扫描电镜观察，核孔复合体具有八重对称结构。\n\n【读图讲解】用冷冻蚀刻电镜从核膜中央劈开并复型观察，可见核孔复合体(NPC)呈八重对称的环状结构，由胞质环、核质环、辐和中央栓（中央颗粒）组成，直径约 120 nm。它既是核质物质交换的通道，又参与对大分子运输的选择性：小分子可扩散通过，mRNA、核糖体亚基、蛋白质等大分子则需信号序列与转运受体介导的主动运输。","page":17,"level":"理解","img":"assets/img/ch05/p017.jpg","anim":null,"fig":null,"points":["冷冻蚀刻与高分辨率扫描电镜显示","核孔复合体具有八重对称结构"],"check":{"q":"冷冻蚀刻与高分辨率扫描电镜显示，核孔复合体呈现的对称结构是？","o":["A. 六重对称","B. 四重对称","C. 九重对称","D. 八重对称"],"a":"D","e":"冷冻蚀刻与高分辨率扫描电镜显示，核孔复合体具有八重对称结构。","oe":["六重对称不符合核孔复合体的电镜观察结果。","四重对称与NPC的八重对称结构不符。","九重对称常见于中心粒描述，并非NPC特征。","电镜显示核孔复合体具有八重对称结构。"]},"cards":null,"mem":"冷冻蚀刻/高分辨扫描电镜显示核孔八重对称","big":"assets/img/ch05/big/p017.jpg","summary":"用冷冻蚀刻电镜技术和高分辨率扫描电镜观察，核孔复合体具有八重对称结构","goal":"学完应能理解并说明「NPC电镜观察」。","experiment":"【方法】冷冻蚀刻电镜从核膜中央劈开，再复型观察，可见核孔复合体呈八重对称的环状结构；高分辨扫描电镜也可显示其表面形态。","intuition":"核孔像“海关闸口”：外观是八重对称的圆环，小分子自由通行，大分子要凭“通行证”主动过。","terms":[{"t":"核孔复合体","en":"nuclear pore complex (NPC)","d":"核膜上介导核质物质交换的巨大蛋白复合体，呈八重对称。"},{"t":"八重对称","en":"octagonal symmetry","d":"NPC 在电镜下呈现的八次旋转对称结构特征。"}]},{"i":4,"sec":"第二节 细胞核","title":"NPC结构-胞质环 (p19)","notes":"核孔复合体(NPC)结构模型(纵向看)：胞质面一侧为胞质环(cytoplasmic ring)/外环，环上有8条短纤毛伸向胞质。","page":19,"level":"掌握","img":"assets/img/ch05/p019.jpg","anim":"npc_model","fig":"核孔复合体的纵向结构：胞质面有胞质环和短纤维，核质面有核质环、长纤维和核篮；辐从边缘伸向中心。横切面呈辐射状八重对称，纵向核质面 vs 胞质面结构不对称(功能不同)。","points":["纵向看NPC结构，胞质面一侧为胞质环(外环)","环上有8条短纤毛伸向胞质"],"check":{"q":"核孔复合体纵向上，胞质环（外环）的结构特征是？","o":["A. 位于核质面一侧，伸出8条短纤毛","B. 位于核孔边缘胞质面一侧，环上有8条短纤毛伸向胞质","C. 位于核膜中央，无纤毛结构","D. 由8条长纤毛伸向核质"],"a":"B","e":"核孔复合体的胞质环位于核孔边缘胞质面一侧，环上有8条短纤毛伸向胞质。","oe":["胞质环位于胞质面而非核质面，故错误。","正确，胞质环在胞质面并有8条短纤毛。","胞质环有8条短纤毛，并非无纤毛。","伸出的是8条短纤毛且朝向胞质，故错误。"]},"cards":[{"front":"NPC胞质环位于何处？有何结构特征？","back":"位于核孔边缘胞质面一侧；环上有8条短纤毛伸向胞质","mnemonic":"胞质环8纤毛，朝外伸","type":"定位","useImg":true,"blank":"短纤毛","blank2":"核孔边缘胞质面一侧"}],"mem":"胞质环8纤毛，朝外伸","big":"assets/img/ch05/big/p019.jpg","summary":"核孔复合体(NPC)结构模型(纵向看)：胞质面一侧为胞质环(cytoplasmic ring)/外环，环上有8条短纤毛伸向胞质","goal":"学完应能掌握并运用「NPC结构-胞质环」的核心内容，能解释其机制、比较相关概念。","intuition":"核孔的胞质面有一个“胞质环”，环上伸出 8 条短纤毛——像门外的“触须”，参与识别和引导货物。"},{"i":5,"sec":"第二节 细胞核","title":"核篮结构 (p20)","notes":"核被膜的胞质面与核质面：核质面一侧有核篮结构(basket)，由8条纤丝汇聚成环。","page":20,"level":"掌握","img":"assets/img/ch05/p020.jpg","anim":null,"fig":null,"points":["核质面一侧有核篮结构","核篮由8条纤丝汇聚成环"],"check":{"q":"核篮(basket)结构位于核被膜的哪一侧，如何构成？","o":["A. 核质面，由13条纤丝汇聚成环","B. 胞质面，由8条纤丝汇聚成环","C. 核质面，由8条纤丝汇聚成环","D. 胞质面，由6条纤丝汇聚成环"],"a":"C","e":"核篮位于核被膜的核质面一侧，由8条纤丝汇聚成环。","oe":["构成核篮的是8条纤丝，不是13条。","核篮位于核被膜的核质面一侧，而非胞质面。","核篮位于核质面，由8条纤丝汇聚成环。","核篮位于核质面，且由8条纤丝构成。"]},"cards":[{"front":"核篮结构位于NPC的哪一侧？由什么组成？","back":"核质面一侧；由8条纤丝汇聚成环","mnemonic":"核篮在核内，8丝汇成环","type":"定位","useImg":true,"blank":"纤丝","blank2":"核质面一侧"}],"mem":"核篮在核内，8丝汇成环","big":"assets/img/ch05/big/p020.jpg","terms":[{"t":"核篮","en":"basket","d":"核孔复合体核质面一侧由8条纤丝汇聚成的篮状结构。"}],"summary":"核被膜的胞质面与核质面：核质面一侧有核篮结构(basket)，由8条纤丝汇聚成环","goal":"学完应能掌握并运用「核篮结构」的核心内容，能解释其机制、比较相关概念。","intuition":"核孔的核质面挂着一个“核篮”，由 8 条纤丝汇成环——像门内的“接收筐”，参与核质运输。"},{"i":6,"sec":"第二节 细胞核","title":"NPC功能-物质运输 (p21)","notes":"核孔复合体(NPC)功能：物质运输——双方向(入核&出核转运)。①亲核蛋白(NLS信号序列)的核输入(如染色质包装蛋白)；②核输出。","page":21,"level":"掌握","img":"assets/img/ch05/p021.jpg","anim":null,"fig":null,"points":["核孔复合体功能：双向的入核与出核转运。","亲核蛋白(含 NLS)入核；RNA、核糖体亚基(含 NES)出核。","入核/出核都是主动运输、高度选择、可调节、耗能。"],"check":{"q":"核孔复合体的物质运输功能特点是？","o":["A. 只允许亲核蛋白入核，不允许出核","B. 双向运输，亲核蛋白（含NLS）入核、其他分子出核","C. 被动扩散，不耗能、无选择性","D. 只运输RNA出核，不运输蛋白"],"a":"B","e":"核孔复合体功能为物质运输，是双向的入核与出核转运；亲核蛋白（含NLS）入核，另有一些分子出核，过程主动、高度选择且耗能。","oe":["NPC为双向通道，出核入核均进行。","正确，双向运输，亲核蛋白入核、其他分子出核。","该运输主动、有选择性且耗能，故错误。","NPC也运输蛋白入核，非只运RNA，故错误。"]},"cards":[{"front":"核孔复合体(NPC)的物质运输功能体现在哪两个方面？","back":"双方向转运：入核转运（亲核蛋白经NLS引导）与出核转运。","mnemonic":"有进有出，双向通行","type":"功能","useImg":true,"blank":"双方向转运","blank2":"入核转运"}],"mem":"有进有出，双向通行","big":"assets/img/ch05/big/p021.jpg","summary":"核孔复合体(NPC)功能：物质运输——双方向(入核&出核转运)","goal":"学完应能掌握并运用「NPC功能-物质运输」的核心内容，能解释其机制、比较相关概念。","intuition":"核孔是“双向海关”：进核的是核蛋白、转录因子，出核的是 mRNA、tRNA、核糖体亚基，各有各的通行信号。"},{"i":7,"sec":"第二节 细胞核","title":"NPC双功能 (p22)","notes":"NPC双功能：①被动运输——离子、小分子代谢产物、分子量约40~60kDa以下的小分子物质可自由扩散出入细胞核(原则上)；②主动运输——大分子经NLS/NES主动转运。","page":22,"level":"掌握","img":"assets/img/ch05/p022.jpg","anim":null,"fig":"核孔复合体的双功能：①被动运输——离子、小分子代谢物、分子量约 40~60kDa 以下的小分子可自由扩散；②主动运输——大分子、RNP 颗粒经中央运输蛋白主动运输，具高度选择性、需信号序列和载体、耗能。","points":["被动运输：约40~60kDa以下的小分子可自由扩散出入核","主动运输：大分子经NLS/NES主动转运"],"check":{"q":"关于核孔复合体的双功能，下列叙述正确的是？","o":["A. 所有蛋白质都能自由扩散通过核孔","B. 约40~60kDa以下的小分子物质可自由扩散出入核","C. 大分子不依赖NLS/NES即可主动转运","D. 离子和小分子代谢产物不能通过NPC"],"a":"B","e":"NPC具被动扩散与主动运输双重功能，40~60kDa以下小分子可自由扩散，大分子经NLS/NES主动转运。","oe":["大分子不能自由扩散，需主动运输。","约40~60kDa以下小分子可自由扩散出入核。","大分子主动转运需NLS/NES等信号引导。","离子和小分子代谢产物可通过NPC扩散。"]},"cards":[{"front":"NPC的被动运输与主动运输有何区别？","back":"被动：离子、小分子代谢物、约40~60kDa以下小分子自由扩散；主动：大分子经NLS/NES耗能转运。","mnemonic":"小的自由过，大的要信号","type":"对比","useImg":true,"blank":"自由扩散","blank2":"主动"}],"mem":"小的自由过，大的要信号","big":"assets/img/ch05/big/p022.jpg","summary":"NPC双功能：①被动运输——离子、小分子代谢产物、分子量约40~60kDa以下的小分子物质可自由扩散出入细胞核(原则上)；②主动运输——大分子经NLS/NES主动转运","goal":"学完应能掌握并运用「NPC双功能」的核心内容，能解释其机制、比较相关概念。","intuition":"核孔像“两道通行的门”：小分子可自由扩散通过（被动），大分子要凭 NLS/NES 主动、耗能地进出。"},{"i":8,"sec":"第二节 细胞核","title":"核孔运输 (p23)","notes":"后转运的核孔运输——细胞核，通过核孔复合体(nuclear pores)实现核质物质交换。\n\n【读图讲解】\n该图演示“后转运的核孔运输”。左侧为细胞核整体，标出核仁(nucleolus)、带核孔的核膜(nuclear envelope with nuclear pores)以及与之相连的内质网(ER)，红箭头指出核孔所在。右侧放大核孔复合体(nuclear pores)，并以虚线分为两栏：左栏为扩散(Diffusion)，允许离子、代谢物及小于40kDa的小蛋白通过；右栏为主动运输(Active transport)，负责转运大于40kDa的蛋白、hnRNP，以及mRNA、tRNA、hnRNP等。要点：核孔是双向选择性通道，小分子靠扩散，大分子靠主动运输与信号序列调控。","page":23,"level":"掌握","img":"assets/img/ch05/p023.jpg","anim":"nuclear_pore_transport","fig":"后转运的核孔运输：亲核蛋白(含 NLS)在胞质合成后，经核孔复合体进入细胞核。图显示蛋白从胞质穿过 NPC 进入核质。关键：NLS 是入核信号，运输是主动的。","points":["通过核孔复合体实现核质物质交换","扩散：离子、代谢物及小于40kDa的小蛋白","主动运输：大于40kDa的蛋白、hnRNP、mRNA、tRNA等"],"check":{"q":"根据核孔运输示意图，下列关于核孔转运的叙述正确的是？","o":["A. 离子与代谢物只能通过主动运输进入核","B. 大于40kDa的蛋白及mRNA经主动运输通过核孔","C. 小于40kDa的小蛋白以主动运输方式通过核孔","D. hnRNP通过核孔自由扩散进入细胞质"],"a":"B","e":"核孔是双向选择性通道，小分子靠扩散，大于40kDa的蛋白及mRNA、tRNA、hnRNP靠主动运输。","oe":["离子与代谢物以扩散方式通过核孔。","大于40kDa的蛋白及mRNA经主动运输通过核孔。","小于40kDa的小蛋白以扩散方式通过核孔。","hnRNP属大分子，需主动运输而非扩散。"]},"cards":[{"front":"细胞核与细胞质之间的物质交换通过什么结构实现？","back":"核孔复合体(nuclear pores)，实现核质物质交换。","mnemonic":"核质往来，核孔为门","type":"定位","useImg":true,"blank":"核孔复合体","blank2":"核质物质交换"}],"mem":"核质往来，核孔为门","big":"assets/img/ch05/big/p023.jpg","terms":[{"t":"核仁","en":"nucleolus","d":"核内合成rRNA并装配核糖体亚基的结构。"}],"summary":"后转运的核孔运输——细胞核，通过核孔复合体(nuclear pores)实现核质物质交换","goal":"学完应能掌握并运用「核孔运输」的核心内容，能解释其机制、比较相关概念。","intuition":"核孔是“双向海关”：<40kDa 的小分子自由过，大的（蛋白、RNA）要出示信号、耗能才放行。"},{"i":9,"sec":"第二节 细胞核","title":"核运输基本概念 (p24)","notes":"物质出入细胞核的运输机制基本概念：核蛋白(nuclear protein)、核定位信号(nuclear localization signal, NLS)、核输出信号(NES)。\n\n【本页英文讲解】\n本页给出物质出入细胞核运输的基本概念。核蛋白（nuclear protein）指在细胞质中合成、需进入细胞核发挥功能的蛋白质；核定位信号（nuclear localization signal, NLS）是引导其入核的氨基酸序列；核输出信号（nuclear export signal, NES）引导核内蛋白出核。考点：NLS与NES是核质运输的方向性信号。","page":24,"level":"掌握","img":"assets/img/ch05/p024.jpg","anim":"nuclear_import","fig":null,"points":["核蛋白：细胞质中合成、进入核内发挥功能","NLS为入核信号；NES为出核信号"],"check":{"q":"关于核定位信号(NLS)与核输出信号(NES)，下列叙述正确的是？","o":["A. NLS是引导蛋白入核的氨基酸序列","B. NLS引导核内蛋白出核","C. NES引导细胞质蛋白入核","D. NLS与NES均为脂类信号分子"],"a":"A","e":"NLS引导核蛋白入核，NES引导核内蛋白出核，二者均为氨基酸序列并决定运输方向。","oe":["NLS是引导核蛋白入核的氨基酸序列。","引导核内蛋白出核的是NES而非NLS。","NES引导核内蛋白出核，不是引导入核。","NLS与NES都是氨基酸序列，不是脂类。"]},"cards":[{"front":"物质出入细胞核运输机制的三个基本概念是什么？","back":"核蛋白(nuclear protein)；核定位信号(NLS)；核输出信号(NES)。","mnemonic":"蛋白、进信号、出信号","type":"定义","useImg":false,"blank":"核定位信号","blank2":"核输出信号"}],"mem":"蛋白、进信号、出信号","big":"assets/img/ch05/big/p024.jpg","summary":"物质出入细胞核的运输机制基本概念：核蛋白(nuclear protein)、核定位信号(nuclear localization signal, NLS)、核输出信号(NES)","goal":"学完应能掌握并运用「核运输基本概念」的核心内容，能解释其机制、比较相关概念。","intuition":"记三个词：核蛋白（进核发挥功能）、NLS（进核信号）、NES（出核信号），方向由信号决定。"},{"i":10,"sec":"第二节 细胞核","title":"核蛋白与亲核蛋白 (p25)","notes":"核蛋白(nuclear protein)/亲核蛋白(karyophilic protein)：细胞质中合成后需要或能够进入细胞核内发挥功能的蛋白质。\n\n【本页英文讲解】\n本页界定核蛋白（nuclear protein）与亲核蛋白（karyophilic protein）。二者指在细胞质中合成后，需要或能够进入细胞核内发挥功能的蛋白质。亲核蛋白这一名称强调其“亲核”特性，即具有被转运进核的能力，通常依赖核定位信号（NLS）。考点：其合成场所为细胞质核糖体，功能场所在核内。","page":25,"level":"掌握","img":"assets/img/ch05/p025.jpg","anim":null,"fig":null,"points":["核蛋白/亲核蛋白：细胞质中合成后需或能进入细胞核发挥功能的蛋白质","其入核通常依赖核定位信号NLS"],"check":{"q":"关于核蛋白（亲核蛋白）的叙述，正确的是？","o":["A. 在细胞核内合成并在核内发挥功能","B. 在细胞质中合成后进入细胞核内发挥功能","C. 在细胞质中合成并在细胞质中发挥功能","D. 合成后直接扩散入核，不依赖任何信号"],"a":"B","e":"核蛋白（亲核蛋白）指在细胞质中合成后需要或能够进入细胞核内发挥功能的蛋白质，通常依赖核定位信号（NLS）。","oe":["核蛋白由胞质核糖体合成，非核内合成。","正确，胞质合成后进核发挥功能。","其功能场所在核内而非胞质，故错误。","入核通常依赖NLS，且为主动运输。"]},"cards":[{"front":"什么是核蛋白（亲核蛋白）？","back":"在细胞质中合成后，需要或能够进入细胞核内发挥功能的蛋白质。","mnemonic":"胞质造，核内用","type":"定义","useImg":false,"blank":"细胞质","blank2":"细胞核"}],"mem":"胞质造，核内用","big":"assets/img/ch05/big/p025.jpg","summary":"核蛋白(nuclear protein)/亲核蛋白(karyophilic protein)：细胞质中合成后需要或能够进入细胞核内发挥功能的蛋白质","goal":"学完应能掌握并运用「核蛋白与亲核蛋白」的核心内容，能解释其机制、比较相关概念。","intuition":"核蛋白像“要去核里上班的人”：在胞质造好，靠 NLS 进核，工作在核内。"},{"i":11,"sec":"第二节 细胞核","title":"核定位信号(NLS) (p26)","notes":"核定位序列/核定位信号(nuclear localization sequence/signal, NLS)：亲核蛋白含有的特殊氨基酸序列，引导蛋白入核。通常富含碱性氨基酸(如PKKKRKV)。","page":26,"level":"掌握","img":"assets/img/ch05/p026.jpg","anim":"nls","fig":"核定位序列/信号(NLS)：亲核蛋白特有的氨基酸序列(短片段，4–8 个氨基酸)，保证蛋白能被转运进核。特点：①存在于亲核蛋白内；②一段连续序列(如 SV40 T 抗原 NLS)或分成两段；③不切除，是蛋白永久部分。","points":["NLS：亲核蛋白含有的特殊氨基酸序列，引导蛋白入核","NLS通常富含碱性氨基酸(如PKKKRKV)"],"check":{"q":"关于核定位信号（NLS），下列叙述正确的是？","o":["A. 是一段特殊氨基酸序列，通常富含碱性氨基酸","B. 是富含亮氨酸的序列","C. 位于蛋白质C端，入核后被切除","D. 属脂类信号分子，与氨基酸序列无关"],"a":"A","e":"NLS是亲核蛋白含有的特殊氨基酸序列，引导蛋白入核，通常富含碱性氨基酸（如PKKKRKV）。","oe":["正确，NLS为富含碱性氨基酸的序列。","富含亮氨酸的是核输出信号NES，故错误。","NLS通常不被切除，且不一定位于C端。","NLS是氨基酸序列而非脂类，故错误。"]},"cards":[{"front":"什么是核定位信号(NLS)？其氨基酸组成有何特点？","back":"亲核蛋白含有的特殊氨基酸序列，引导蛋白入核；通常富含碱性氨基酸（如PKKKRKV）。","mnemonic":"碱性序列，入核通行证","type":"定义","useImg":false,"blank":"亲核蛋白","blank2":"碱性氨基酸"}],"mem":"碱性序列，入核通行证","big":"assets/img/ch05/big/p026.jpg","summary":"核定位序列/核定位信号(nuclear localization sequence/signal, NLS)：亲核蛋白含有的特殊氨基酸序列，引导蛋白入核","goal":"学完应能掌握并运用「核定位信号(NLS)」的核心内容，能解释其机制、比较相关概念。","intuition":"NLS 像“进核通行证”：亲核蛋白自带的短序列（常富含碱性氨基酸），被 importin 识别后带入核；它一般不切除、可反复使用。"},{"i":12,"sec":"第二节 细胞核","title":"NLS引导入核 (p28)","notes":"Nuclear-localization signal(NLS) directs proteins to the cell nucleus——NLS引导蛋白进入细胞核。\n\n【本页英文讲解】\n本页说明核定位信号（nuclear-localization signal, NLS）引导蛋白进入细胞核。NLS是蛋白质上的一段特定氨基酸序列，可被输入蛋白（importin）识别，从而介导货物蛋白经核孔复合体入核。NLS通常不被切除，可反复使用。考点：NLS引导入核需与核输出信号（NES）及Ran-GTP调控相联系。","page":28,"level":"掌握","img":"assets/img/ch05/p028.jpg","anim":null,"fig":null,"points":["NLS被输入蛋白(importin)识别","介导货物蛋白经核孔复合体入核；NLS通常不被切除、可反复使用"],"check":{"q":"NLS引导蛋白进入细胞核的机制中，正确的是？","o":["A. NLS被核输出受体识别，介导蛋白出核","B. NLS在发挥作用后被立即切除，只能使用一次","C. NLS被输入蛋白（importin）识别，介导货物经核孔入核","D. NLS直接为入核提供ATP"],"a":"C","e":"NLS是可被输入蛋白（importin）识别的氨基酸序列，介导货物蛋白经核孔复合体入核，且通常不被切除、可反复使用。","oe":["识别NLS的是输入蛋白而非核输出受体。","NLS通常不被切除、可反复使用，故错误。","正确，NLS被importin识别并介导货物入核。","NLS是识别信号，不直接提供能量。"]},"cards":[{"front":"NLS的功能是什么？","back":"核定位信号引导蛋白质进入细胞核。","mnemonic":"NLS指路，蛋白入核","type":"功能","useImg":true,"blank":"核定位信号","blank2":"细胞核"}],"mem":"NLS指路，蛋白入核","big":"assets/img/ch05/big/p028.jpg","summary":"Nuclear-localization signal(NLS) directs proteins to the cell nucleus——NLS引导蛋白进入细胞核","goal":"学完应能掌握并运用「NLS引导入核」的核心内容，能解释其机制、比较相关概念。","intuition":"NLS 像“进核通行证”：被 importin 识别后带入核，且一般不切除、可反复使用。"},{"i":13,"sec":"第二节 细胞核","title":"NLS主动运输 (p29)","notes":"大蛋白进入细胞核需要有核定位信号(NLS)。亲核蛋白通过核孔复合体是一主动运输过程，需消耗能量。","page":29,"level":"掌握","img":"assets/img/ch05/p029.jpg","anim":null,"fig":null,"points":["大蛋白进入细胞核需要有核定位信号(NLS)","亲核蛋白通过核孔复合体是主动运输过程，需消耗能量"],"check":{"q":"亲核蛋白通过核孔复合体进入细胞核的过程是？","o":["A. 自由扩散，不需要NLS","B. 被动运输，但需NLS","C. 胞吞作用，形成囊泡入核","D. 主动运输过程，需要NLS且消耗能量"],"a":"D","e":"大蛋白进入细胞核需要有核定位信号（NLS）；亲核蛋白通过核孔复合体是一主动运输过程，需消耗能量。","oe":["大蛋白入核需NLS且非自由扩散，故错误。","被动运输不耗能，与主动运输不符。","入核经核孔复合体，非胞吞囊泡方式。","正确，为需NLS并耗能的主动运输。"]},"cards":[{"front":"大蛋白进入细胞核需要什么条件？该过程有何特点？","back":"需有核定位信号(NLS)；经核孔复合体进行主动运输，需消耗能量。","mnemonic":"大蛋白入核，信号加耗能","type":"流程","useImg":false,"blank":"核定位信号","blank2":"核孔复合体"}],"mem":"大蛋白入核，信号加耗能","big":"assets/img/ch05/big/p029.jpg","summary":"大蛋白进入细胞核需要有核定位信号(NLS)","goal":"学完应能掌握并运用「NLS主动运输」的核心内容，能解释其机制、比较相关概念。","intuition":"大分子进核是“主动运输”：要带 NLS、过核孔，还要耗能，不是想进就进。"},{"i":14,"sec":"第二节 细胞核","title":"核输出信号(NES) (p30)","notes":"核输出信号(nuclear export signal, NES)：核内物质输出细胞核的信号，帮助核内某些分子通过核孔进入细胞质。通常是富含亮氨酸的序列。","page":30,"level":"掌握","img":"assets/img/ch05/p030.jpg","anim":null,"fig":null,"points":["NES是核内物质输出细胞核的信号","NES通常是富含亮氨酸的序列"],"check":{"q":"关于核输出信号（NES），下列叙述正确的是？","o":["A. 引导胞质蛋白入核，通常富含碱性氨基酸","B. 位于蛋白质N端，出核后被切除","C. 引导核内物质输出细胞核，通常富含亮氨酸","D. 与NLS完全相同，二者可互换"],"a":"C","e":"NES是核内物质输出细胞核的信号，帮助核内某些分子通过核孔进入细胞质，通常是富含亮氨酸的序列。","oe":["引导入核、富含碱性氨基酸的是NLS。","NES是出核信号，通常不被切除。","正确，NES引导出核且富含亮氨酸。","NES与NLS功能相反，不可互换。"]},"cards":[{"front":"核输出信号(NES)的功能是什么？其序列特征如何？","back":"介导核内物质输出细胞核，帮助分子通过核孔进入细胞质；通常为富含亮氨酸的序列","mnemonic":"出核靠亮氨酸","type":"功能","useImg":false,"blank":"核内物质","blank2":"亮氨酸"}],"mem":"出核靠亮氨酸","big":"assets/img/ch05/big/p030.jpg","summary":"核输出信号(nuclear export signal, NES)：核内物质输出细胞核的信号，帮助核内某些分子通过核孔进入细胞质","goal":"学完应能掌握并运用「核输出信号(NES)」的核心内容，能解释其机制、比较相关概念。","intuition":"NES 像“出核通行证”：核内某些分子带富含亮氨酸的 NES，被带出核到胞质工作。"},{"i":15,"sec":"第二节 细胞核","title":"输入蛋白importin (p31)","notes":"亲核蛋白必须与水溶性的NLS受体结合才能穿过核孔复合体，这种受体称importin(输入蛋白)。分布在胞质溶胶中，识别、结合核蛋白的NLS。","page":31,"level":"掌握","img":"assets/img/ch05/p031.jpg","anim":null,"fig":null,"points":["亲核蛋白须与NLS受体结合才能穿过核孔复合体","该受体称importin(输入蛋白)，分布于胞质溶胶，识别结合NLS"],"check":{"q":"关于输入蛋白（importin）的叙述，正确的是？","o":["A. 分布在核内，识别NES","B. 是一种膜脂，构成核孔","C. 可水解GTP，直接驱动蛋白入核","D. 是水溶性的NLS受体，分布于胞质溶胶，识别结合核蛋白的NLS"],"a":"D","e":"亲核蛋白必须与水溶性的NLS受体结合才能穿过核孔复合体，这种受体即importin，分布在胞质溶胶中，识别并结合核蛋白的NLS。","oe":["importin在胞质溶胶且识别NLS，非识别NES。","importin是蛋白质而非膜脂，故错误。","importin本身不水解GTP，供能由Ran等参与。","正确，importin为胞质中的水溶性NLS受体。"]},"cards":[{"front":"输入蛋白(importin)是什么？分布在哪里？","back":"亲核蛋白的NLS受体，水溶性；分布在胞质溶胶中，识别并结合核蛋白的NLS","mnemonic":"输入蛋白在胞质，认NLS带进门","type":"定义","useImg":false,"blank":"NLS受体","blank2":"胞质溶胶"}],"mem":"输入蛋白在胞质，认NLS带进门","big":"assets/img/ch05/big/p031.jpg","summary":"亲核蛋白必须与水溶性的NLS受体结合才能穿过核孔复合体，这种受体称importin(输入蛋白)","goal":"学完应能掌握并运用「输入蛋白importin」的核心内容，能解释其机制、比较相关概念。","intuition":"importin 像“进核的摆渡车”：在胞质识别货物上的 NLS、把它载过核孔；到核内卸货后再返回。"},{"i":16,"sec":"第二节 细胞核","title":"Ran-GTP的作用 (p32)","notes":"The Ran-GTP(mainly in nucleus) binding causes the receptors to release——Ran-GTP(主要在核内)结合输入蛋白，使其释放货物蛋白。Ran是核质运输的关键调控GTP酶。\n\n【本页英文讲解】\n本页讲Ran-GTP的作用。Ran-GTP（主要在核内）与输入蛋白（importin）结合，使受体释放其运载的货物蛋白（cargo）。Ran是核质运输的关键调控GTP酶（GTPase），其GTP/GDP结合状态在核内外分布不同，驱动货物的装载与释放。考点：Ran-GTP在核内促使货物释放，是核输入循环的核心。","page":32,"level":"掌握","img":"assets/img/ch05/p032.jpg","anim":"ran_cycle","fig":"Ran GTPase 对入核和出核都必需。核内 Ran-GTP 浓度高、胞质 Ran-GDP 高(由 Ran-GEF 和 Ran-GAP 维持)。Ran-GTP 在核内结合入核受体使其释放货物；Ran-GDP 在胞质使出核受体释放货物。图是 Ran 的核质梯度。","points":["Ran-GTP主要存在于核内","Ran-GTP结合输入蛋白，使其释放货物蛋白","Ran是核质运输的关键调控GTP酶"],"check":{"q":"关于Ran-GTP在核质运输中的作用，正确的是？","o":["A. Ran-GTP结合货物蛋白，使其进入核孔","B. Ran是ATP酶，结合ATP后释放货物","C. Ran-GTP（主要在核内）结合输入蛋白，使其释放货物蛋白","D. Ran-GTP使输入蛋白与货物结合更牢固"],"a":"C","e":"Ran是核质运输的关键调控GTP酶；Ran-GTP（主要在核内）结合输入蛋白，使受体释放其运载的货物蛋白。","oe":["Ran-GTP作用于输入蛋白而非直接结合货物。","Ran是GTP酶而非ATP酶，且促货物释放。","正确，Ran-GTP结合输入蛋白促使货物释放。","Ran-GTP促使释放而非结合更牢固，故错误。"]},"cards":[{"front":"Ran-GTP在核质运输中的作用是什么？","back":"在核内结合输入蛋白，使其释放货物蛋白；Ran是核质运输的关键调控GTP酶","mnemonic":"核内Ran-GTP一到，货物就下车","type":"功能","useImg":false,"blank":"输入蛋白","blank2":"GTP酶"}],"mem":"核内Ran-GTP一到，货物就下车","big":"assets/img/ch05/big/p032.jpg","terms":[{"t":"Ran-GTP","en":"Ran-GTP","d":"核质运输的关键调控GTP酶，主要存在于核内；结合输入蛋白后促使其释放货物。"}],"summary":"The Ran-GTP(mainly in nucleus) binding causes the receptors to release——Ran-GTP(主要在核内)结合输入","goal":"学完应能掌握并运用「Ran-GTP的作用」的核心内容，能解释其机制、比较相关概念。","intuition":"核质运输的方向由 Ran 的“开关”决定：核内 Ran-GTP 多，像“到站信号”，让输入蛋白卸下货物；胞质 Ran-GTP 少，输入蛋白保持“载货”状态直到进核。Ran-GTP/GDP 在核内外的不对称分布，相当于给运输安了一个“单向阀”。"},{"i":17,"sec":"第二节 细胞核","title":"入核转运过程 (p34)","notes":"亲核蛋白通过NPC的入核转运：NLS-亲核蛋白→细胞质中受体importin识别并结合形成转运复合物→经NPC入核→核内Ran-GTP结合importin→释放货物→importin回收出核。","page":34,"level":"掌握","img":"assets/img/ch05/p034.jpg","anim":"importin_import","fig":"亲核蛋白经 NPC 的入核转运：NLS-亲核蛋白 + importin 形成转运复合物 → 与 NPC 胞质纤维结合、NPC 构象改变 → 由胞质面转到核质面 → 与 Ran-GTP 结合、复合物解离释放货物 → importin α/β 与 Ran-GTP 返回胞质，Ran-GTP 水解成 Ran-GDP、与 importin 解离。","points":["NLS-亲核蛋白→胞质中importin识别并结合形成转运复合物→经NPC入核","核内Ran-GTP结合importin→释放货物→importin回收出核"],"check":{"q":"亲核蛋白经NPC入核的过程中，下列步骤正确的是？","o":["A. importin在核内识别NLS并与货物结合","B. Ran-GTP在细胞质中促进转运复合物形成","C. 货物入核后Ran-GTP使importin与货物结合更紧密","D. importin在细胞质识别NLS并结合货物形成转运复合物"],"a":"D","e":"细胞质中importin识别NLS-亲核蛋白并形成转运复合物，入核后核内Ran-GTP结合importin释放货物，importin回收出核。","oe":["importin在细胞质而非核内识别并结合NLS货物。","Ran-GTP在核内起作用，而非细胞质。","核内Ran-GTP结合importin，促使货物释放。","细胞质中importin识别NLS并使货物形成复合物。"]},"cards":[{"front":"亲核蛋白经NPC入核转运的主要步骤是什么？","back":"NLS-亲核蛋白与胞质importin结合成转运复合物；经NPC入核；核内Ran-GTP结合importin释放货物；importin回收出核","mnemonic":"结合→入核→Ran释放→回收","type":"流程","useImg":true,"blank":"importin","blank2":"Ran-GTP"}],"mem":"结合→入核→Ran释放→回收","big":"assets/img/ch05/big/p034.jpg","summary":"亲核蛋白通过NPC的入核转运：NLS-亲核蛋白→细胞质中受体importin识别并结合形成转运复合物→经NPC入核→核内Ran-GTP结合importin→释放货物→importi","goal":"学完应能掌握并运用「入核转运过程」的核心内容，能解释其机制、比较相关概念。","intuition":"入核像一个“有进有出的循环”：NLS-货物在胞质被 importin 识别、带过核孔；核内 Ran-GTP 让 importin 卸货并把它送回胞质，importin 再去接下一批。方向由 Ran 的分布决定。"}],"mcq":[{"id":"ch05_mcq_13","mod":"模块二：核孔运输","modI":1,"q":"核孔复合体(NPC)的结构包括？","o":["A. 胞质环、核篮结构","B. 仅一个孔","C. 双层膜","D. 网格蛋白"],"a":"A","e":"NPC纵向结构：胞质环(外环，8条短纤毛)、核质面的核篮结构，具八重对称。","kp":"ch05_s1_2","oe":["正确。NPC含胞质环与核篮结构，整体呈八重对称。","错误。NPC结构复杂，并非只是一个简单的孔。","错误。双层膜指核被膜本身，不是核孔复合体的结构。","错误。网格蛋白参与膜泡包被，不是NPC的组成成分。"]},{"id":"ch05_mcq_14","mod":"模块二：核孔运输","modI":1,"q":"亲核蛋白入核运输属于？","o":["A. 被动扩散","B. 主动运输(需能量)","C. 自由扩散","D. 胞吞"],"a":"B","e":"大蛋白经NPC入核是主动运输过程，需NLS、importin和Ran-GTP，消耗能量。","kp":"ch05_s1_10","oe":["错误。亲核蛋白入核需NLS和Ran并耗能，不属被动扩散。","正确。入核需NLS、importin与Ran-GTP，消耗能量。","错误。自由扩散针对小分子，大蛋白入核需主动运输。","错误。入核经NPC转运，并不是胞吞途径。"]},{"id":"ch05_mcq_15","mod":"模块二：核孔运输","modI":1,"q":"线粒体蛋白运输的特点不包括？","o":["A. 翻译后转移","B. 需N端导肽","C. 需解折叠","D. 需保持折叠状态"],"a":"D","e":"线粒体蛋白必须解折叠(Hsp70帮助)才能导入，而非保持折叠。","kp":"ch05_s1_6","oe":["错误。线粒体蛋白确为翻译后转移，属其特点，故非本题所问。","错误。线粒体蛋白运输确需N端导肽引导，属其特点。","错误。前体确需Hsp70帮助解折叠，属其特点。","正确。线粒体蛋白必须解折叠才能导入，而非保持折叠状态。"]},{"id":"ch05_mcq_16","mod":"模块二：核孔运输","modI":1,"q":"核输出信号(NES)通常是？","o":["A. 富含亮氨酸的序列","B. 富含赖氨酸的序列","C. KDEL","D. M6P"],"a":"A","e":"NES通常是富含亮氨酸的序列，帮助核内分子输出到细胞质。NLS通常富含碱性氨基酸。","kp":"ch05_s1_14","oe":["正确。NES通常是富含亮氨酸的序列，介导蛋白输出到细胞质。","错误。富含赖氨酸的碱性序列多为NLS，而非NES。","错误。KDEL是内质网驻留信号，不是核输出信号。","错误。M6P是溶酶体酶的分选信号，与核输出无关。"]},{"id":"ch05_mcq_17","mod":"模块二：核孔运输","modI":1,"q":"Ran-GTP在核质运输中的作用是？","o":["A. 结合importin使其释放货物","B. 组装网格蛋白","C. 水解脂类","D. 合成蛋白"],"a":"A","e":"Ran-GTP(主要在核内)结合importin，使其释放货物蛋白，实现核内定向释放。","kp":"ch05_s1_16","oe":["正确。核内Ran-GTP结合importin，促使其释放货物蛋白。","错误。组装网格蛋白与膜泡包被有关，非Ran的功能。","错误。Ran是一种GTP酶，不催化脂类的水解。","错误。Ran不参与蛋白质的合成过程。"]},{"id":"ch05_mcq_18","mod":"模块二：核孔运输","modI":1,"q":"叶绿体基质中的Rubisco小亚基由？","o":["A. 核基因编码,翻译后转运","B. 叶绿体基因编码","C. 线粒体基因编码","D. 无基因编码"],"a":"A","e":"Rubisco的8个小亚基由核基因编码，在胞质合成后翻译后转运入叶绿体基质；大亚基由叶绿体基因编码。","kp":"ch05_s1_0","oe":["正确。小亚基由核基因编码，胞质合成后转运入叶绿体基质。","错误。叶绿体基因编码的是Rubisco的大亚基。","错误。线粒体基因并不编码Rubisco的组分。","错误。小亚基有基因编码，并非无基因编码。"]},{"id":"ch05_mcq_19","mod":"模块二：核孔运输","modI":1,"q":"过氧化物酶体蛋白的引导信号是？","o":["A. PTS1/PTS2","B. NLS","C. KDEL","D. M6P"],"a":"A","e":"过氧化物酶体蛋白经PTS1(多数,C端SKL)/PTS2信号被导入。其发生有两种途径：ER出芽从头形成、已有酶体分裂。","kp":"ch05_s1_11","oe":["正确。PTS1(多为C端SKL)和PTS2引导蛋白进入过氧化物酶体。","错误。NLS导向细胞核，不是过氧化物酶体的引导信号。","错误。KDEL是内质网驻留信号，与过氧化物酶体无关。","错误。M6P导向溶酶体酶的分选，非过氧化物酶体。"]},{"id":"ch05_mcq_20","mod":"模块二：核孔运输","modI":1,"q":"下列属于翻译后转移的蛋白是？","o":["A. 分泌蛋白","B. 线粒体基质蛋白","C. 溶酶体酶","D. 质膜受体"],"a":"B","e":"线粒体、叶绿体、过氧化物酶体蛋白是翻译后转移；分泌蛋白、溶酶体酶、质膜蛋白经ER共翻译转移。","kp":"ch05_s1_10","oe":["错误。分泌蛋白经内质网共翻译转运，不属翻译后转移。","正确。线粒体基质蛋白在胞质合成后，翻译后转运入线粒体。","错误。溶酶体酶经内质网共翻译转运再分选，非翻译后转移。","错误。质膜受体经内质网共翻译转运后运至质膜。"]}],"judge":[{"id":"ch05_judge_4","modI":1,"q":"核孔复合体(NPC)通道直径约9-10nm，约40~60kDa以下的小分子可自由扩散出入。","a":"对","e":"NPC通道直径约9-10nm，40~60kDa以下小分子可自由扩散；大分子经NLS/NES主动运输。","kp":"ch05_s1_2","oe":["核孔复合体通道直径约9-10nm，40~60kDa以下小分子可自由扩散出入。","误记核孔通道直径或可自由扩散的分子量阈值，故判错。"]},{"id":"ch05_judge_5","modI":1,"q":"引导蛋白质进入细胞核的信号是NES，引导出核的信号是NLS。","a":"错","e":"入核信号是NLS(核定位信号)，出核信号是NES(核输出信号)。","kp":"ch05_s1_12","oe":["若以为入核信号是NES、出核信号是NLS则判对，把二者名称记反。","入核信号是NLS(核定位信号)，出核信号是NES(核输出信号)，不可混淆。"]},{"id":"ch05_judge_6","modI":1,"q":"亲核蛋白通过核孔复合体是主动运输过程，需消耗能量。","a":"对","e":"大分子经NPC入核是主动运输，需NLS、importin和Ran-GTP，消耗能量。","kp":"ch05_s1_13","oe":["亲核蛋白入核需NLS、importin和Ran-GTP参与，属主动运输并消耗能量。","若判为错，多误认为入核靠自由扩散，实则依赖载体并水解GTP供能。"]},{"id":"ch05_judge_7","modI":1,"q":"调控核质运输的关键GTP酶是Ran。","a":"对","e":"Ran是核质运输的关键GTP酶；Ran-GTP(核内)结合importin使其释放货物。","kp":"ch05_s1_16","oe":["Ran是核质运输的关键GTP酶，核内Ran-GTP结合importin使货物释放。","若判为错，多因混淆其他GTP酶，实则调控核质运输的关键酶就是Ran。"]}],"fill":[{"id":"ch05_fill_4","modI":1,"q":"核孔复合体(NPC)通道直径约________nm,约________kDa以下小分子可自由扩散出入。","a":"8-10,40","kp":"ch05_s1_2","oe":["核孔复合体通道直径约8-10nm，允许小分子被动扩散出入。","约40kDa以下的小分子可自由扩散通过核孔，故填40。"]},{"id":"ch05_fill_5","modI":1,"q":"引导蛋白入核的信号是________,引导出核的信号是________。","a":"NLS(核定位信号),NES(核输出信号)","kp":"ch05_s1_11","oe":["NLS是引导亲核蛋白入核的短肽信号，故第一空填NLS。","NES是引导蛋白出核的信号，通常富含亮氨酸，故填NES。"]},{"id":"ch05_fill_6","modI":1,"q":"识别NLS的胞质受体是________；调控核质运输的关键GTP酶是________。","a":"importin(输入蛋白),Ran","kp":"ch05_s1_16","oe":["胞质输入蛋白importin识别NLS并携带货物蛋白入核。","Ran是调控核质运输的关键小G蛋白(GTP酶)，故填Ran。"]},{"id":"ch05_fill_9","modI":1,"q":"亲核蛋白通过核孔复合体是________运输过程,需消耗________。","a":"主动,能量","kp":"ch05_s1_13","oe":["亲核蛋白经核孔复合体是主动、选择性的运输过程，故填主动。","该运输依赖Ran-GTP水解供能，故需消耗能量，填能量。"]},{"id":"ch05_fill_10","modI":1,"q":"NPC的纵向结构包括胞质面的________环和核质面的________结构。","a":"胞质(外),核篮","kp":"ch05_s1_4","oe":["NPC胞质面有胞质环，并伸出胞质纤维，故第一空填胞质环。","NPC核质面有核篮状结构，故第二空填核篮。"]},{"id":"ch05_fill_12","modI":1,"q":"亲核蛋白入核时,核内Ran-________结合importin,使其________货物蛋白。","a":"GTP,释放","kp":"ch05_s1_15","oe":["核内Ran与GTP结合成Ran-GTP，与importin结合致货物释放。","Ran-GTP结合importin使其构象改变，从而释放货物蛋白。"]}],"short":[{"id":"ch05_short_2","modI":1,"q":"简述核孔复合体的结构及核质运输机制。","a":"核孔复合体(NPC)及核质运输：\n\n【结构】\n①所有真核细胞间期核普遍存在；\n②通道直径9-10nm，外径约120nm；\n③八重对称：胞质环(外环，8条短纤毛)、核质面的核篮结构。\n\n【运输功能(双功能)】\n①被动运输：离子、小分子代谢产物、40~60kDa以下小分子自由扩散出入；\n②主动运输：大分子经NLS/NES转运。\n\n【入核机制】\n①亲核蛋白含核定位信号(NLS，富含碱性氨基酸)；\n②胞质中importin(输入蛋白)识别并结合NLS，形成转运复合物；\n③经NPC入核；\n④核内Ran-GTP结合importin，释放货物蛋白；\n⑤importin回收出核。\n\n【出核机制】\n①货物含核输出信号(NES，富含亮氨酸)；\n②exportin识别NES，经NPC出核。\n\n【意义】\n实现核质双向物质交换，是基因表达调控的基础。","kp":"ch05_s1_2"},{"id":"ch05_short_4","modI":1,"q":"简述亲核蛋白入核转运的分子机制。","a":"亲核蛋白入核转运机制：\n\n【关键分子】\n①核定位信号(NLS)：亲核蛋白含有的特殊氨基酸序列，通常富含碱性氨基酸(如PKKKRKV)；\n②importin(输入蛋白)：胞质中的NLS受体；\n③Ran：核质运输的关键GTP酶。\n\n【过程】\n①NLS-亲核蛋白在细胞质中与importin识别并结合，形成转运复合物；\n②转运复合物经核孔复合体(NPC)进入细胞核；\n③核内Ran-GTP结合importin，使其构象改变，释放货物蛋白；\n④importin-Ran-GTP复合物返回细胞质，Ran水解GTP，importin循环使用。\n\n【特点】\n①主动运输，消耗能量；\n②方向性由Ran-GTP的核内浓度梯度决定。\n\n【对照出核】\n核输出信号(NES)+exportin介导出核。\n\n【意义】\n是基因表达调控、细胞周期等的基础。","kp":"ch05_s1_17"}],"calc":[{"id":"ch05_calc_2","modI":1,"q":"论述细胞核与细胞质之间物质运输的机制及意义。","a":"核质运输通过核孔复合体实现,由NLS/NES和Ran-GTP精密调控","steps":"【结构基础】\n核孔复合体(NPC)：通道直径9-10nm，外径约120nm，八重对称(胞质环+核篮)，间期核普遍存在。\n\n【运输类型】\n①被动运输：40~60kDa以下小分子自由扩散；\n②主动运输：大分子经NLS/NES。\n\n【入核机制】\n①亲核蛋白含NLS(富含碱性氨基酸)；\n②胞质importin识别结合NLS；\n③经NPC入核；\n④核内Ran-GTP结合importin释放货物。\n\n【出核机制】\n①货物含NES(富含亮氨酸)；\n②exportin识别NES，经NPC出核。\n\n【方向性】\nRan-GTP在核内浓度高、胞质低→决定运输方向。\n\n【意义】\n①实现核质物质交换(蛋白、RNA)；\n②是基因表达调控的基础(转录因子入核)；\n③参与细胞周期、信号转导、病毒感染等；\n④核质运输异常与疾病相关。","kp":"ch05_s1_6"}],"term":[{"id":"ch05_term_3","modI":1,"term":"核孔复合体(NPC)","def":"①真核细胞间期核膜上介导核质物质交换的通道复合体（定义）。②结构：通道直径9-10nm，外径约120nm，八重对称(胞质环+核篮)（结构）。③功能：双功能——被动运输(40~60kDa以下小分子)、主动运输(NLS/NES大分子)（功能）。","kps":"踩分点:①定义(1分)②结构(1分)③双功能(2分)","kp":"ch05_s1_2"},{"id":"ch05_term_4","modI":1,"term":"核定位信号(NLS)","def":"①亲核蛋白含有的、引导其进入细胞核的特殊氨基酸序列（定义）。②特点：通常富含碱性氨基酸(如PKKKRKV)（特点）。③机制：被胞质importin识别结合，经NPC入核（机制）。","kps":"踩分点:①定义(1分)②富含碱性氨基酸(1分)③机制(1分)","kp":"ch05_s1_11"},{"id":"ch05_term_5","modI":1,"term":"核输出信号(NES)","def":"①核内物质输出细胞核的信号序列（定义）。②特点：通常富含亮氨酸（特点）。③机制：被exportin识别，经核孔出核（机制）。","kps":"踩分点:①定义(1分)②富含亮氨酸(1分)③机制(1分)","kp":"ch05_s1_14"},{"id":"ch05_term_6","modI":1,"term":"输入蛋白(Importin)","def":"①胞质溶胶中的NLS受体（定义）。②功能：识别并结合亲核蛋白的NLS，形成转运复合物，经NPC入核（功能）。③调控：核内Ran-GTP结合importin使其释放货物（调控）。","kps":"踩分点:①定义(1分)②功能(1分)③Ran-GTP调控(1分)","kp":"ch05_s1_15"},{"id":"ch05_term_7","modI":1,"term":"Ran蛋白","def":"①核质运输的关键GTP酶（定义）。②功能：Ran-GTP(主要在核内)结合importin使其释放货物蛋白，决定运输方向（功能）。③意义：Ran-GTP的核内浓度梯度是核质运输方向性的基础（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch05_s1_16"},{"id":"ch05_term_12","modI":1,"term":"核篮结构","def":"①核孔复合体核质面一侧的篮状结构（定义）。②组成：由8条纤丝汇聚成环（组成）。③功能：参与核质物质运输（功能）。","kps":"踩分点:①定义(1分)②组成(1分)③功能(1分)","kp":"ch05_s1_5"}]},{"i":2,"name":"模块三：过氧化物酶体","slides":[{"i":0,"sec":"第三节 过氧化物酶体","title":"过氧化物酶体 (p35)","notes":"过氧化物酶体(peroxisome)：单层膜围绕成的细胞器，又称微体(microbody)。含多种氧化酶和过氧化氢酶。鼠肝细胞超薄切片显示过氧化物酶体和线粒体。","page":35,"level":"掌握","img":"assets/img/ch05/p035.jpg","anim":null,"fig":"过氧化物酶体(peroxisome)：单层膜围绕的细胞器，又称微体。含多种氧化酶和过氧化氢酶，能分解脂肪酸、解毒。图中鼠肝细胞超薄切片显示过氧化物酶体(圆形小体)和线粒体。","points":["过氧化物酶体是单层膜围绕成的细胞器，又称微体","含多种氧化酶和过氧化氢酶"],"check":{"q":"关于过氧化物酶体，下列叙述正确的是？","o":["A. 单层膜围绕，又称微体，含多种氧化酶和过氧化氢酶","B. 由双层膜包被，含多种水解酶","C. 是合成ATP的主要场所","D. 不含酶，仅起机械支撑作用"],"a":"A","e":"过氧化物酶体是单层膜围绕成的细胞器，又称微体（microbody），含多种氧化酶和过氧化氢酶。","oe":["正确，单层膜、又称微体、含氧化酶与过氧化氢酶。","过氧化物酶体为单层膜且含氧化酶，故错误。","合成ATP主要在线粒体，非过氧化物酶体。","其含多种酶类，并非仅机械支撑。"]},"cards":[{"front":"过氧化物酶体的结构特点和主要酶是什么？","back":"单层膜围绕的细胞器，又称微体；含多种氧化酶和过氧化氢酶","mnemonic":"单层膜微体，氧化酶+过氧化氢酶","type":"组成","useImg":true,"blank":"过氧化氢酶","blank2":"氧化酶"}],"mem":"单层膜微体，氧化酶+过氧化氢酶","big":"assets/img/ch05/big/p035.jpg","summary":"过氧化物酶体(peroxisome)：单层膜围绕成的细胞器，又称微体(microbody)","goal":"学完应能掌握并运用「过氧化物酶体」的核心内容，能解释其机制、比较相关概念。","intuition":"过氧化物酶体像细胞的“有毒废料处理罐”：单层膜，装氧化酶和过氧化氢酶，处理脂肪酸氧化产生的 H₂O₂。"},{"i":1,"sec":"第三节 过氧化物酶体","title":"过氧化物酶体的发生 (p37)","notes":"过氧化物酶体的生物发生与分裂：蛋白质主要在细胞质基质游离核糖体合成，但有两种发生途径：①过氧化物酶体的一些膜蛋白Pex3/Pex16来自内质网；②新过氧化物酶体形成。","page":37,"level":"掌握","img":"assets/img/ch05/p037.jpg","anim":"peroxisome","fig":"过氧化物酶体的生物发生：蛋白质在胞质游离核糖体合成，有两种发生途径——①一些膜蛋白(Pex3/Pex16)来自内质网；②由已有过氧化物酶体分裂。图给出两种途径的模型。","points":["蛋白主要在细胞质基质游离核糖体合成","一些膜蛋白(Pex3/Pex16)来自内质网"],"check":{"q":"关于过氧化物酶体的生物发生，正确的是？","o":["A. 所有蛋白均由内质网合成","B. 蛋白质全部在线粒体合成","C. 只能由已有过氧化物酶体分裂形成，不能从头形成","D. 蛋白质主要在胞质游离核糖体合成，部分膜蛋白Pex3/Pex16来自内质网"],"a":"D","e":"过氧化物酶体蛋白主要在细胞质基质游离核糖体合成；其发生有两种途径，一些膜蛋白（Pex3/Pex16）来自内质网，另有新过氧化物酶体形成。","oe":["多数蛋白在胞质游离核糖体合成，故错误。","过氧化物酶体蛋白不在线粒体合成，多由胞质游离核糖体合成。","既能由已有过氧化物酶体分裂，也能从头形成，故该说法错误。","正确，多在胞质合成，部分膜蛋白来自ER。"]},"cards":[{"front":"过氧化物酶体蛋白在哪里合成？其发生有何特点？","back":"蛋白质主要在细胞质基质游离核糖体合成；发生与分裂相关，部分膜蛋白Pex3/Pex16来自内质网","mnemonic":"游离核糖体造蛋白，ER供膜","type":"流程","useImg":false,"blank":"细胞质基质游离核糖体","blank2":"内质网"}],"mem":"游离核糖体造蛋白，ER供膜","big":"assets/img/ch05/big/p037.jpg","summary":"过氧化物酶体的生物发生与分裂：蛋白质主要在细胞质基质游离核糖体合成，但有两种发生途径：①过氧化物酶体的一些膜蛋白Pex3/Pex16来自内质网；②新过氧化物酶体形成","goal":"学完应能掌握并运用「过氧化物酶体的发生」的核心内容，能解释其机制、比较相关概念。","intuition":"过氧化物酶体“半自建”：蛋白在胞质造好后送入，部分膜来自 ER，还能靠已有酶体分裂。"},{"i":2,"sec":"第三节 过氧化物酶体","title":"两种形成途径 (p38)","notes":"新过氧化物酶体形成的两种途径：①从头形成(由ER出芽)；②由已有过氧化物酶体分裂。过氧化物酶体蛋白经PTS信号(PTS1/PTS2)被导入。","page":38,"level":"掌握","img":"assets/img/ch05/p038.jpg","anim":null,"fig":"新过氧化物酶体形成的两种途径：①从头形成(由 ER 出芽)；②由已有过氧化物酶体分裂。过氧化物酶体蛋白经 PTS 信号(PTS1 多数为 C 端 SKL，PTS2 为 N 端)被导入。图对比两条途径。","points":["新过氧化物酶体的两种形成途径：从头形成(ER出芽)、由已有过氧化物酶体分裂","过氧化物酶体蛋白经PTS1/PTS2信号被导入"],"check":{"q":"新过氧化物酶体形成的两种途径是？","o":["A. 仅由从头形成","B. ①从头形成（由ER出芽）②由已有过氧化物酶体分裂","C. 仅由线粒体分裂形成","D. 由高尔基体直接产生"],"a":"B","e":"新过氧化物酶体形成有两条途径：从头形成（由ER出芽）和由已有过氧化物酶体分裂；蛋白经PTS信号被导入。","oe":["除从头形成外还可由已有酶体分裂，故错误。","正确，即ER出芽从头形成与已有酶体分裂。","两种途径与线粒体分裂无关，故该选项错误。","过氧化物酶体不由高尔基体直接产生。"]},"cards":[{"front":"新过氧化物酶体形成的两种途径是什么？蛋白靠什么信号导入？","back":"①从头形成(由ER出芽)；②由已有过氧化物酶体分裂；蛋白经PTS1/PTS2信号导入","mnemonic":"从头出芽或分裂，PTS指路","type":"流程","useImg":false,"blank":"PTS1/PTS2信号","blank2":"过氧化物酶体分裂"}],"mem":"从头出芽或分裂，PTS指路","big":"assets/img/ch05/big/p038.jpg","terms":[{"t":"PTS1/PTS2","en":"PTS1/PTS2","d":"过氧化物酶体靶向信号，引导蛋白被导入过氧化物酶体。"}],"summary":"新过氧化物酶体形成的两种途径：①从头形成(由ER出芽)；②由已有过氧化物酶体分裂","goal":"学完应能掌握并运用「两种形成途径」的核心内容，能解释其机制、比较相关概念。","intuition":"新过氧化物酶体像“新开分店或老店复制”：既可由 ER 出芽从头形成，也可由已有酶体一分为二；蛋白靠 PTS1/PTS2 信号导入。"}],"mcq":[{"id":"ch05_mcq_21","mod":"模块三：过氧化物酶体","modI":2,"q":"NPC被动运输的分子量上限约为？","o":["A. 40~60kDa","B. 100kDa","C. 10kDa","D. 500kDa"],"a":"A","e":"约40~60kDa以下的小分子物质可自由扩散出入细胞核(原则上，但许多小分子例外)。","kp":null,"oe":["正确。约40~60kDa以下小分子可经NPC自由扩散出入细胞核。","错误。100kDa的大分子需主动运输，不能自由扩散。","错误。上限约40~60kDa，并非仅为10kDa。","错误。500kDa远超过被动运输的分子量上限。"]},{"id":"ch05_mcq_22","mod":"模块三：过氧化物酶体","modI":2,"q":"线粒体蛋白前体在胞质解折叠需要？","o":["A. Hsp70和ATP","B. 网格蛋白","C. SNARE","D. Ran"],"a":"A","e":"前体蛋白在胞质与Hsp70结合，ATP→ADP，解折叠为松散结构后才能导入线粒体。","kp":"ch05_s2_0","oe":["正确。胞质Hsp70结合前体并水解ATP，使其解折叠成松散结构。","错误。网格蛋白参与膜泡包被，与蛋白解折叠无关。","错误。SNARE介导膜泡融合，不参与前体解折叠。","错误。Ran参与核质运输，不参与线粒体前体的解折叠。"]},{"id":"ch05_mcq_23","mod":"模块三：过氧化物酶体","modI":2,"q":"亲核蛋白的NLS通常富含？","o":["A. 碱性氨基酸(如赖氨酸/精氨酸)","B. 酸性氨基酸","C. 疏水氨基酸","D. 无特定氨基酸"],"a":"A","e":"NLS通常富含碱性氨基酸(如SV40大T抗原的PKKKRKV)，带正电，与importin结合。","kp":"ch05_s2_1","oe":["正确。NLS富含赖氨酸、精氨酸等碱性氨基酸，带正电荷。","错误。酸性氨基酸带负电，与NLS富含碱性氨基酸不符。","错误。疏水氨基酸不构成NLS的序列特征。","错误。NLS有特定氨基酸组成，并非无特定氨基酸。"]},{"id":"ch05_mcq_24","mod":"模块三：过氧化物酶体","modI":2,"q":"核孔复合体存在于？","o":["A. 间期细胞核","B. 分裂期","C. 线粒体","D. 溶酶体"],"a":"A","e":"所有真核细胞(酵母、人)间期细胞核普遍存在NPC，是核质交换通道。","kp":null,"oe":["正确。NPC普遍存在于真核细胞的间期核被膜上。","错误。分裂期核膜解体，NPC消失，非其存在部位。","错误。线粒体上没有核孔复合体。","错误。溶酶体上没有核孔复合体。"]},{"id":"ch05_mcq_25","mod":"模块三：过氧化物酶体","modI":2,"q":"叶绿体蛋白分选不包括？","o":["A. 基质蛋白","B. 类囊体腔蛋白","C. 类囊体膜蛋白","D. 核蛋白"],"a":"D","e":"叶绿体蛋白分选：基质蛋白、类囊体腔蛋白、类囊体膜蛋白。核蛋白经核孔运输，不属叶绿体分选。","kp":"ch05_s2_2","oe":["错误。基质蛋白属叶绿体蛋白分选，故不是本题所问。","错误。类囊体腔蛋白属叶绿体蛋白分选。","错误。类囊体膜蛋白属叶绿体蛋白分选。","正确。核蛋白经核孔运输，不属叶绿体蛋白分选。"]}],"judge":[{"id":"ch05_judge_8","modI":2,"q":"过氧化物酶体的蛋白引导信号是PTS1/PTS2。","a":"对","e":"过氧化物酶体蛋白经PTS1(多数,C端SKL)或PTS2信号被导入。","kp":"ch05_s2_1","oe":["过氧化物酶体蛋白主要经C端PTS1(SKL)或N端PTS2信号被导入。","若判为错，可能误认其靠其他信号，实则PTS1/PTS2是其引导信号。"]},{"id":"ch05_judge_9","modI":2,"q":"过氧化物酶体只有一种发生途径，即由内质网出芽形成。","a":"错","e":"过氧化物酶体有两种发生途径：ER出芽从头形成、已有过氧化物酶体分裂。","kp":"ch05_s2_1","oe":["若判对则误认为仅内质网出芽一种途径，忽略酶体还可分裂发生。","过氧化物酶体有两条发生途径：内质网出芽从头形成与已有酶体分裂。"]}],"fill":[{"id":"ch05_fill_7","modI":2,"q":"过氧化物酶体又称________,其蛋白引导信号是________,发生有ER出芽和________两种途径。","a":"微体(microbody),PTS1/PTS2,已有酶体分裂","kp":"ch05_s2_1","oe":["过氧化物酶体因体积小又称微体，含氧化酶和过氧化氢酶。","过氧化物酶体蛋白的引导信号为PTS1或PTS2，故为答案。","过氧化物酶体可由ER出芽生成，也可由已有酶体分裂产生。"]}],"short":[{"id":"ch05_short_6","modI":2,"q":"简述过氧化物酶体的发生及蛋白导入。","a":"过氧化物酶体的发生及蛋白导入：\n\n【结构】\n单层膜围绕的细胞器，又称微体(microbody)，含氧化酶和过氧化氢酶。\n\n【蛋白合成】\n过氧化物酶体蛋白主要在细胞质基质游离核糖体合成。\n\n【两种发生途径】\n①从头形成：过氧化物酶体的一些膜蛋白Pex3/Pex16来自内质网，由ER出芽形成新的过氧化物酶体；\n②分裂：由已有过氧化物酶体分裂产生。\n\n【蛋白导入】\n①经PTS1(多数蛋白，C端SKL序列)或PTS2(少数)信号；\n②由Pex蛋白(受体)识别；\n③可折叠状态即可导入(与线粒体需解折叠不同)。\n\n【意义】\n保证过氧化物酶体的生物发生和功能(脂肪酸氧化、过氧化氢分解)。","kp":"ch05_s2_1"}],"calc":[],"term":[{"id":"ch05_term_9","modI":2,"term":"过氧化物酶体(Peroxisome)","def":"①单层膜围绕的细胞器，又称微体(microbody)（定义）。②组成：含氧化酶和过氧化氢酶（组成）。③发生：两种途径——ER出芽从头形成、已有酶体分裂（发生）。④蛋白导入：经PTS1/PTS2信号（导入）。","kps":"踩分点:①定义(1分)②组成(1分)③发生(1分)④PTS信号(1分)","kp":"ch05_s2_0"},{"id":"ch05_term_13","modI":2,"term":"PTS信号","def":"①过氧化物酶体蛋白的靶向信号(PTS1/PTS2)（定义）。②PTS1：多数过氧化物酶体蛋白，C端SKL序列；PTS2：少数蛋白，N端（分类）。③功能：由Pex蛋白受体识别，引导蛋白导入过氧化物酶体（功能）。","kps":"踩分点:①定义(1分)②PTS1/PTS2(2分)③功能(1分)","kp":"ch05_s2_2"}]}],"mcq":[{"id":"ch05_mcq_1","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体蛋白N端的引导序列称为？","o":["A. 信号肽","B. 导肽(presequence)","C. 转运肽","D. 前导序列"],"a":"B","e":"线粒体蛋白N端为导肽(presequence)；叶绿体蛋白N端为转运肽(transit peptide)。两者都是翻译后转移的引导信号。","kp":"ch05_s0_2","oe":["信号肽通常指引导分泌蛋白进入内质网的序列，非线粒体。","线粒体蛋白N端的引导序列称为导肽（presequence）。","转运肽指叶绿体蛋白N端的引导序列，非线粒体。","前导序列是泛指名称，线粒体引导序列标准称导肽。"]},{"id":"ch05_mcq_2","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体蛋白前体进入基质需要？","o":["A. 保持折叠状态","B. 由Hsp70帮助解折叠","C. 直接穿过膜","D. 经核孔"],"a":"B","e":"Only unfolded proteins can be imported——前体蛋白在胞质与Hsp70结合，ATP水解后解折叠，才能经TOM/TIM进入线粒体。","kp":"ch05_s0_6","oe":["错误。前体必须解折叠才可被导入，保持折叠无法通过TOM/TIM。","正确。胞质Hsp70结合前体并水解ATP，使其解折叠后经TOM/TIM进入基质。","错误。需借助TOM/TIM转运复合体，不能直接穿过线粒体膜。","错误。核孔是核质运输通道，线粒体蛋白不经核孔进入基质。"]},{"id":"ch05_mcq_3","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体蛋白前体跨膜转运发生在？","o":["A. 任意膜位置","B. 内外膜接触点","C. 核孔","D. 高尔基体"],"a":"B","e":"前体蛋白到线粒体基质的转移只发生在少数线粒体内外膜相'接触点'，经TOM(外膜)和TIM(内膜)复合体。","kp":"ch05_s0_3","oe":["错误。并非任意膜位置，只在少数内外膜接触点进行转运。","正确。前体经内外膜接触点的TOM与TIM复合体转运进入基质。","错误。核孔介导核质运输，与线粒体蛋白跨膜转运无关。","错误。高尔基体参与膜泡运输，不参与线粒体蛋白导入。"]},{"id":"ch05_mcq_4","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"叶绿体蛋白N端的引导序列称为？","o":["A. 导肽","B. 转运肽(transit peptide)","C. 信号肽","D. NLS"],"a":"B","e":"叶绿体前体蛋白N端含转运肽(transit peptide)，引导入叶绿体后被切除。","kp":"ch05_s0_8","oe":["错误。导肽多指线粒体蛋白引导序列，叶绿体特称转运肽。","正确。叶绿体前体蛋白N端为转运肽，引导入叶绿体后被切除。","错误。信号肽引导蛋白进入内质网，属共翻译转运。","错误。NLS是核定位信号，负责引导蛋白进入细胞核。"]},{"id":"ch05_mcq_5","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"类囊体腔蛋白的转运肽特点是？","o":["A. 只有一段","B. 分2个区(导向基质+导向类囊体腔)","C. 无引导功能","D. 位于C端"],"a":"B","e":"类囊体腔蛋白的转运肽分2区：N端导向叶绿体基质序列，接下来是导向类囊体腔的序列，分两步引导。","kp":"ch05_s0_10","oe":["错误。并非只有一段，而是分导向基质与类囊体腔两个区。","正确。转运肽分两区，先导向叶绿体基质，再导向类囊体腔。","错误。转运肽具有引导功能，可定向运输蛋白至类囊体腔。","错误。转运肽位于蛋白N端，而不是C端。"]},{"id":"ch05_mcq_6","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"核孔复合体(NPC)的直径(通道)约为？","o":["A. 9-10nm","B. 120nm","C. 1nm","D. 50nm"],"a":"A","e":"NPC通道直径约9-10nm，外径约120nm；40~60kDa以下小分子可自由扩散。","kp":"ch05_s1_2","oe":["正确。NPC通道直径约9-10nm，小分子物质可自由扩散通过。","错误。120nm是核孔复合体的外径，不是其通道直径。","错误。1nm过小，远小于实际通道，多数分子无法通过。","错误。50nm大于实际通道直径，与事实不符。"]},{"id":"ch05_mcq_7","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"引导蛋白质进入细胞核的信号是？","o":["A. NLS(核定位信号)","B. NES","C. KDEL","D. M6P"],"a":"A","e":"NLS(核定位信号)引导亲核蛋白入核；NES(核输出信号)介导出核；KDEL是ER驻留信号；M6P是溶酶体信号。","kp":"ch05_s1_11","oe":["正确。NLS核定位信号引导亲核蛋白经NPC进入细胞核。","错误。NES是核输出信号，介导核内蛋白输出到细胞质。","错误。KDEL是内质网驻留信号，使蛋白滞留于内质网。","错误。M6P是溶酶体酶的分选信号，导向溶酶体。"]},{"id":"ch05_mcq_8","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"识别并结合NLS的胞质受体是？","o":["A. importin(输入蛋白)","B. exportin","C. SRP","D. dynamin"],"a":"A","e":"亲核蛋白必须与NLS受体importin结合才能穿过NPC。importin分布在胞质溶胶中。","kp":"ch05_s1_15","oe":["正确。胞质中importin识别并结合NLS，介导货物蛋白入核。","错误。exportin介导含NES的货物蛋白从核内输出。","错误。SRP识别信号肽，介导分泌蛋白的共翻译转运。","错误。dynamin是参与膜泡颈缩的GTP酶，与入核无关。"]},{"id":"ch05_mcq_9","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"调控核质运输的关键GTP酶是？","o":["A. Ran","B. Rab","C. Sar","D. ARF"],"a":"A","e":"Ran是核质运输的关键GTP酶。Ran-GTP(主要在核内)结合importin使其释放货物蛋白。","kp":"ch05_s1_16","oe":["正确。Ran是核质运输的关键GTP酶，Ran-GTP调控货物释放。","错误。Rab调控膜泡运输与融合，不参与核质运输。","错误。Sar参与内质网到高尔基体的膜泡形成。","错误。ARF参与膜泡形成与囊泡运输，非核质运输。"]},{"id":"ch05_mcq_10","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"40~60kDa以下的小分子出入细胞核的方式是？","o":["A. 主动运输","B. 被动扩散(经NPC)","C. 胞吞","D. 跨膜转运"],"a":"B","e":"NPC双功能：离子、小分子代谢产物、40~60kDa以下小分子可自由扩散出入核；大分子经NLS/NES主动运输。","kp":"ch05_s1_7","oe":["错误。小分子经NPC自由扩散，不属消耗能量的主动运输。","正确。40~60kDa以下小分子可经NPC自由扩散出入细胞核。","错误。胞吞是大分子物质入胞方式，并不是入核方式。","错误。经核孔扩散进入，而非跨脂双层膜的跨膜转运。"]},{"id":"ch05_mcq_11","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体外膜和内膜的蛋白转运子分别是？","o":["A. TOM和TIM","B. TIM和TOM","C. SRP和SR","D. NPC"],"a":"A","e":"外膜转运子TOM复合体、内膜转运子TIM复合体，前体蛋白经TOM进入、经TIM进入基质。","kp":"ch05_s0_4","oe":["正确。外膜转运子为TOM复合体，内膜转运子为TIM复合体。","错误。顺序颠倒，外膜是TOM，内膜是TIM。","错误。SRP与SR参与内质网共翻译转运，与线粒体无关。","错误。NPC是核孔复合体，负责核质之间的运输。"]},{"id":"ch05_mcq_12","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"过氧化物酶体的另一种名称是？","o":["A. 微体(microbody)","B. 溶酶体","C. 内体","D. 液泡"],"a":"A","e":"过氧化物酶体又称微体(microbody)，单层膜，含氧化酶和过氧化氢酶。","kp":"ch05_s2_0","oe":["正确。过氧化物酶体又称微体，为单层膜细胞器。","错误。溶酶体含酸性水解酶，与过氧化物酶体不同。","错误。内体参与胞吞物质的分选，不是过氧化物酶体。","错误。液泡是植物细胞的贮水细胞器，另属一类。"]},{"id":"ch05_mcq_13","mod":"模块二：核孔运输","modI":1,"q":"核孔复合体(NPC)的结构包括？","o":["A. 胞质环、核篮结构","B. 仅一个孔","C. 双层膜","D. 网格蛋白"],"a":"A","e":"NPC纵向结构：胞质环(外环，8条短纤毛)、核质面的核篮结构，具八重对称。","kp":"ch05_s1_2","oe":["正确。NPC含胞质环与核篮结构，整体呈八重对称。","错误。NPC结构复杂，并非只是一个简单的孔。","错误。双层膜指核被膜本身，不是核孔复合体的结构。","错误。网格蛋白参与膜泡包被，不是NPC的组成成分。"]},{"id":"ch05_mcq_14","mod":"模块二：核孔运输","modI":1,"q":"亲核蛋白入核运输属于？","o":["A. 被动扩散","B. 主动运输(需能量)","C. 自由扩散","D. 胞吞"],"a":"B","e":"大蛋白经NPC入核是主动运输过程，需NLS、importin和Ran-GTP，消耗能量。","kp":"ch05_s1_13","oe":["错误。亲核蛋白入核需NLS和Ran并耗能，不属被动扩散。","正确。入核需NLS、importin与Ran-GTP，消耗能量。","错误。自由扩散针对小分子，大蛋白入核需主动运输。","错误。入核经NPC转运，并不是胞吞途径。"]},{"id":"ch05_mcq_15","mod":"模块二：核孔运输","modI":1,"q":"线粒体蛋白运输的特点不包括？","o":["A. 翻译后转移","B. 需N端导肽","C. 需解折叠","D. 需保持折叠状态"],"a":"D","e":"线粒体蛋白必须解折叠(Hsp70帮助)才能导入，而非保持折叠。","kp":"ch05_s0_2","oe":["错误。线粒体蛋白确为翻译后转移，属其特点，故非本题所问。","错误。线粒体蛋白运输确需N端导肽引导，属其特点。","错误。前体确需Hsp70帮助解折叠，属其特点。","正确。线粒体蛋白必须解折叠才能导入，而非保持折叠状态。"]},{"id":"ch05_mcq_16","mod":"模块二：核孔运输","modI":1,"q":"核输出信号(NES)通常是？","o":["A. 富含亮氨酸的序列","B. 富含赖氨酸的序列","C. KDEL","D. M6P"],"a":"A","e":"NES通常是富含亮氨酸的序列，帮助核内分子输出到细胞质。NLS通常富含碱性氨基酸。","kp":"ch05_s1_14","oe":["正确。NES通常是富含亮氨酸的序列，介导蛋白输出到细胞质。","错误。富含赖氨酸的碱性序列多为NLS，而非NES。","错误。KDEL是内质网驻留信号，不是核输出信号。","错误。M6P是溶酶体酶的分选信号，与核输出无关。"]},{"id":"ch05_mcq_17","mod":"模块二：核孔运输","modI":1,"q":"Ran-GTP在核质运输中的作用是？","o":["A. 结合importin使其释放货物","B. 组装网格蛋白","C. 水解脂类","D. 合成蛋白"],"a":"A","e":"Ran-GTP(主要在核内)结合importin，使其释放货物蛋白，实现核内定向释放。","kp":"ch05_s1_16","oe":["正确。核内Ran-GTP结合importin，促使其释放货物蛋白。","错误。组装网格蛋白与膜泡包被有关，非Ran的功能。","错误。Ran是一种GTP酶，不催化脂类的水解。","错误。Ran不参与蛋白质的合成过程。"]},{"id":"ch05_mcq_18","mod":"模块二：核孔运输","modI":1,"q":"叶绿体基质中的Rubisco小亚基由？","o":["A. 核基因编码,翻译后转运","B. 叶绿体基因编码","C. 线粒体基因编码","D. 无基因编码"],"a":"A","e":"Rubisco的8个小亚基由核基因编码，在胞质合成后翻译后转运入叶绿体基质；大亚基由叶绿体基因编码。","kp":"ch05_s0_11","oe":["正确。小亚基由核基因编码，胞质合成后转运入叶绿体基质。","错误。叶绿体基因编码的是Rubisco的大亚基。","错误。线粒体基因并不编码Rubisco的组分。","错误。小亚基有基因编码，并非无基因编码。"]},{"id":"ch05_mcq_19","mod":"模块二：核孔运输","modI":1,"q":"过氧化物酶体蛋白的引导信号是？","o":["A. PTS1/PTS2","B. NLS","C. KDEL","D. M6P"],"a":"A","e":"过氧化物酶体蛋白经PTS1(多数,C端SKL)/PTS2信号被导入。其发生有两种途径：ER出芽从头形成、已有酶体分裂。","kp":"ch05_s2_1","oe":["正确。PTS1(多为C端SKL)和PTS2引导蛋白进入过氧化物酶体。","错误。NLS导向细胞核，不是过氧化物酶体的引导信号。","错误。KDEL是内质网驻留信号，与过氧化物酶体无关。","错误。M6P导向溶酶体酶的分选，非过氧化物酶体。"]},{"id":"ch05_mcq_20","mod":"模块二：核孔运输","modI":1,"q":"下列属于翻译后转移的蛋白是？","o":["A. 分泌蛋白","B. 线粒体基质蛋白","C. 溶酶体酶","D. 质膜受体"],"a":"B","e":"线粒体、叶绿体、过氧化物酶体蛋白是翻译后转移；分泌蛋白、溶酶体酶、质膜蛋白经ER共翻译转移。","kp":"ch05_s0_0","oe":["错误。分泌蛋白经内质网共翻译转运，不属翻译后转移。","正确。线粒体基质蛋白在胞质合成后，翻译后转运入线粒体。","错误。溶酶体酶经内质网共翻译转运再分选，非翻译后转移。","错误。质膜受体经内质网共翻译转运后运至质膜。"]},{"id":"ch05_mcq_21","mod":"模块三：过氧化物酶体","modI":2,"q":"NPC被动运输的分子量上限约为？","o":["A. 40~60kDa","B. 100kDa","C. 10kDa","D. 500kDa"],"a":"A","e":"约40~60kDa以下的小分子物质可自由扩散出入细胞核(原则上，但许多小分子例外)。","kp":"ch05_s1_7","oe":["正确。约40~60kDa以下小分子可经NPC自由扩散出入细胞核。","错误。100kDa的大分子需主动运输，不能自由扩散。","错误。上限约40~60kDa，并非仅为10kDa。","错误。500kDa远超过被动运输的分子量上限。"]},{"id":"ch05_mcq_22","mod":"模块三：过氧化物酶体","modI":2,"q":"线粒体蛋白前体在胞质解折叠需要？","o":["A. Hsp70和ATP","B. 网格蛋白","C. SNARE","D. Ran"],"a":"A","e":"前体蛋白在胞质与Hsp70结合，ATP→ADP，解折叠为松散结构后才能导入线粒体。","kp":"ch05_s0_7","oe":["正确。胞质Hsp70结合前体并水解ATP，使其解折叠成松散结构。","错误。网格蛋白参与膜泡包被，与蛋白解折叠无关。","错误。SNARE介导膜泡融合，不参与前体解折叠。","错误。Ran参与核质运输，不参与线粒体前体的解折叠。"]},{"id":"ch05_mcq_23","mod":"模块三：过氧化物酶体","modI":2,"q":"亲核蛋白的NLS通常富含？","o":["A. 碱性氨基酸(如赖氨酸/精氨酸)","B. 酸性氨基酸","C. 疏水氨基酸","D. 无特定氨基酸"],"a":"A","e":"NLS通常富含碱性氨基酸(如SV40大T抗原的PKKKRKV)，带正电，与importin结合。","kp":"ch05_s1_11","oe":["正确。NLS富含赖氨酸、精氨酸等碱性氨基酸，带正电荷。","错误。酸性氨基酸带负电，与NLS富含碱性氨基酸不符。","错误。疏水氨基酸不构成NLS的序列特征。","错误。NLS有特定氨基酸组成，并非无特定氨基酸。"]},{"id":"ch05_mcq_24","mod":"模块三：过氧化物酶体","modI":2,"q":"核孔复合体存在于？","o":["A. 间期细胞核","B. 分裂期","C. 线粒体","D. 溶酶体"],"a":"A","e":"所有真核细胞(酵母、人)间期细胞核普遍存在NPC，是核质交换通道。","kp":"ch05_s1_2","oe":["正确。NPC普遍存在于真核细胞的间期核被膜上。","错误。分裂期核膜解体，NPC消失，非其存在部位。","错误。线粒体上没有核孔复合体。","错误。溶酶体上没有核孔复合体。"]},{"id":"ch05_mcq_25","mod":"模块三：过氧化物酶体","modI":2,"q":"叶绿体蛋白分选不包括？","o":["A. 基质蛋白","B. 类囊体腔蛋白","C. 类囊体膜蛋白","D. 核蛋白"],"a":"D","e":"叶绿体蛋白分选：基质蛋白、类囊体腔蛋白、类囊体膜蛋白。核蛋白经核孔运输，不属叶绿体分选。","kp":"ch05_s0_9","oe":["错误。基质蛋白属叶绿体蛋白分选，故不是本题所问。","错误。类囊体腔蛋白属叶绿体蛋白分选。","错误。类囊体膜蛋白属叶绿体蛋白分选。","正确。核蛋白经核孔运输，不属叶绿体蛋白分选。"]}],"judge":[{"id":"ch05_judge_1","modI":0,"q":"线粒体蛋白N端含导肽，叶绿体蛋白N端含转运肽。","a":"对","e":"线粒体蛋白N端为导肽(presequence)，叶绿体蛋白N端为转运肽(transit peptide)。","kp":"ch05_s0_8","oe":["线粒体蛋白N端为导肽，叶绿体蛋白N端为转运肽。","误把线粒体与叶绿体的N端信号名称互换，故判错。"]},{"id":"ch05_judge_2","modI":0,"q":"线粒体蛋白前体必须解折叠后才能被导入线粒体。","a":"对","e":"只有解折叠的蛋白能进入线粒体；前体蛋白在胞质由Hsp70帮助、消耗ATP解折叠。","kp":"ch05_s0_7","oe":["只有解折叠的蛋白能进入线粒体，前体蛋白在胞质由Hsp70耗能解折叠。","误以为折叠态蛋白可直接导入或无需分子伴侣，故判错。"]},{"id":"ch05_judge_3","modI":0,"q":"线粒体外膜和内膜的蛋白转运子分别是TOM和TIM复合体。","a":"对","e":"外膜为TOM复合体、内膜为TIM复合体，前体蛋白经二者进入基质。","kp":"ch05_s0_4","oe":["线粒体外膜为TOM复合体、内膜为TIM复合体，前体蛋白经二者进入基质。","误把TOM与TIM对应的膜或内外顺序记反，故判错。"]},{"id":"ch05_judge_4","modI":1,"q":"核孔复合体(NPC)通道直径约9-10nm，约40~60kDa以下的小分子可自由扩散出入。","a":"对","e":"NPC通道直径约9-10nm，40~60kDa以下小分子可自由扩散；大分子经NLS/NES主动运输。","kp":"ch05_s1_2","oe":["核孔复合体通道直径约9-10nm，40~60kDa以下小分子可自由扩散出入。","误记核孔通道直径或可自由扩散的分子量阈值，故判错。"]},{"id":"ch05_judge_5","modI":1,"q":"引导蛋白质进入细胞核的信号是NES，引导出核的信号是NLS。","a":"错","e":"入核信号是NLS(核定位信号)，出核信号是NES(核输出信号)。","kp":"ch05_s1_12","oe":["若以为入核信号是NES、出核信号是NLS则判对，把二者名称记反。","入核信号是NLS(核定位信号)，出核信号是NES(核输出信号)，不可混淆。"]},{"id":"ch05_judge_6","modI":1,"q":"亲核蛋白通过核孔复合体是主动运输过程，需消耗能量。","a":"对","e":"大分子经NPC入核是主动运输，需NLS、importin和Ran-GTP，消耗能量。","kp":"ch05_s1_13","oe":["亲核蛋白入核需NLS、importin和Ran-GTP参与，属主动运输并消耗能量。","若判为错，多误认为入核靠自由扩散，实则依赖载体并水解GTP供能。"]},{"id":"ch05_judge_7","modI":1,"q":"调控核质运输的关键GTP酶是Ran。","a":"对","e":"Ran是核质运输的关键GTP酶；Ran-GTP(核内)结合importin使其释放货物。","kp":"ch05_s1_16","oe":["Ran是核质运输的关键GTP酶，核内Ran-GTP结合importin使货物释放。","若判为错，多因混淆其他GTP酶，实则调控核质运输的关键酶就是Ran。"]},{"id":"ch05_judge_8","modI":2,"q":"过氧化物酶体的蛋白引导信号是PTS1/PTS2。","a":"对","e":"过氧化物酶体蛋白经PTS1(多数,C端SKL)或PTS2信号被导入。","kp":"ch05_s2_1","oe":["过氧化物酶体蛋白主要经C端PTS1(SKL)或N端PTS2信号被导入。","若判为错，可能误认其靠其他信号，实则PTS1/PTS2是其引导信号。"]},{"id":"ch05_judge_9","modI":2,"q":"过氧化物酶体只有一种发生途径，即由内质网出芽形成。","a":"错","e":"过氧化物酶体有两种发生途径：ER出芽从头形成、已有过氧化物酶体分裂。","kp":"ch05_s2_1","oe":["若判对则误认为仅内质网出芽一种途径，忽略酶体还可分裂发生。","过氧化物酶体有两条发生途径：内质网出芽从头形成与已有酶体分裂。"]},{"id":"ch05_judge_10","modI":0,"q":"叶绿体类囊体腔蛋白的转运肽可分为导向基质和导向类囊体腔两个区。","a":"对","e":"类囊体腔蛋白转运肽分2区：N端导向基质序列+导向类囊体腔序列，分两步引导。","kp":"ch05_s0_10","oe":["类囊体腔蛋白转运肽分N端导向基质区与导向类囊体腔区，分两步引导。","误判为错者多不知转运肽可分导向基质和类囊体腔两个功能区。"]}],"fill":[{"id":"ch05_fill_1","modI":0,"q":"线粒体蛋白N端含________,叶绿体蛋白N端含________,两者都引导翻译后转移。","a":"导肽(presequence),转运肽(transit peptide)","kp":"ch05_s0_8","oe":["线粒体蛋白前体N端的导肽引导其翻译后转运入线粒体。","叶绿体蛋白N端的转运肽引导其翻译后转运入叶绿体。"]},{"id":"ch05_fill_2","modI":0,"q":"线粒体蛋白前体在胞质由________帮助、消耗________解折叠后才能导入。","a":"Hsp70,ATP","kp":"ch05_s0_7","oe":["胞质Hsp70分子伴侣使前体解折叠并保持可转运状态。","前体解折叠由Hsp70消耗ATP驱动，导入过程也需ATP。"]},{"id":"ch05_fill_3","modI":0,"q":"线粒体外膜转运子为________复合体,内膜为________复合体,前体在内外膜________点转运。","a":"TOM,TIM,接触","kp":"ch05_s0_4","oe":["线粒体外膜转运子为TOM复合体，识别并导入前体蛋白。","线粒体内膜转运子为TIM复合体，将前体送入基质。","前体在内外膜相互接触的接触点处协调转运，故填接触点。"]},{"id":"ch05_fill_4","modI":1,"q":"核孔复合体(NPC)通道直径约________nm,约________kDa以下小分子可自由扩散出入。","a":"8-10,40","kp":"ch05_s1_2","oe":["核孔复合体通道直径约8-10nm，允许小分子被动扩散出入。","约40kDa以下的小分子可自由扩散通过核孔，故填40。"]},{"id":"ch05_fill_5","modI":1,"q":"引导蛋白入核的信号是________,引导出核的信号是________。","a":"NLS(核定位信号),NES(核输出信号)","kp":"ch05_s1_11","oe":["NLS是引导亲核蛋白入核的短肽信号，故第一空填NLS。","NES是引导蛋白出核的信号，通常富含亮氨酸，故填NES。"]},{"id":"ch05_fill_6","modI":1,"q":"识别NLS的胞质受体是________；调控核质运输的关键GTP酶是________。","a":"importin(输入蛋白),Ran","kp":"ch05_s1_16","oe":["胞质输入蛋白importin识别NLS并携带货物蛋白入核。","Ran是调控核质运输的关键小G蛋白(GTP酶)，故填Ran。"]},{"id":"ch05_fill_7","modI":2,"q":"过氧化物酶体又称________,其蛋白引导信号是________,发生有ER出芽和________两种途径。","a":"微体(microbody),PTS1/PTS2,已有酶体分裂","kp":"ch05_s2_1","oe":["过氧化物酶体因体积小又称微体，含氧化酶和过氧化氢酶。","过氧化物酶体蛋白的引导信号为PTS1或PTS2，故为答案。","过氧化物酶体可由ER出芽生成，也可由已有酶体分裂产生。"]},{"id":"ch05_fill_8","modI":0,"q":"Rubisco的小亚基由________基因编码,翻译后转运入叶绿体________。","a":"核,基质","kp":"ch05_s0_11","oe":["Rubisco小亚基由核基因编码，大亚基由叶绿体基因编码。","小亚基在胞质合成后经转运肽导入叶绿体基质，再与rbcL大亚基装配。"]},{"id":"ch05_fill_9","modI":1,"q":"亲核蛋白通过核孔复合体是________运输过程,需消耗________。","a":"主动,能量","kp":"ch05_s1_13","oe":["亲核蛋白经核孔复合体是主动、选择性的运输过程，故填主动。","该运输依赖Ran-GTP水解供能，故需消耗能量，填能量。"]},{"id":"ch05_fill_10","modI":1,"q":"NPC的纵向结构包括胞质面的________环和核质面的________结构。","a":"胞质(外),核篮","kp":"ch05_s1_4","oe":["NPC胞质面有胞质环，并伸出胞质纤维，故第一空填胞质环。","NPC核质面有核篮状结构，故第二空填核篮。"]},{"id":"ch05_fill_11","modI":0,"q":"类囊体腔蛋白的转运肽分2区:________序列和导向________的序列。","a":"导向叶绿体基质,类囊体腔","kp":"ch05_s0_10","oe":["转运肽第一区引导蛋白进入叶绿体基质，故填导向叶绿体基质。","第二区引导蛋白由基质进一步进入类囊体腔，故填类囊体腔。"]},{"id":"ch05_fill_12","modI":1,"q":"亲核蛋白入核时,核内Ran-________结合importin,使其________货物蛋白。","a":"GTP,释放","kp":"ch05_s1_16","oe":["核内Ran与GTP结合成Ran-GTP，与importin结合致货物释放。","Ran-GTP结合importin使其构象改变，从而释放货物蛋白。"]}],"short":[{"id":"ch05_short_1","modI":0,"q":"简述线粒体蛋白质翻译后转运的过程。","a":"线粒体蛋白质的翻译后转运：\n\n【特点】\n线粒体绝大多数蛋白由核基因编码，在胞质游离核糖体合成后转运。\n\n【过程】\n①在细胞质基质中，含N端导肽(presequence)的前体蛋白与Hsp70结合，ATP→ADP，解折叠为松散结构；\n②前体蛋白的导肽与线粒体外膜受体识别；\n③在内外膜接触点，经外膜转运子TOM复合体进入；\n④经内膜转运子TIM复合体进入基质；\n⑤导肽被切除，蛋白在基质中重新折叠成活性形式；\n⑥部分蛋白进一步分选到内膜、膜间隙或外膜。\n\n【要点】\n①需N端导肽；②必须解折叠才能导入；③发生在内外膜接触点；④消耗能量(ATP)。\n\n【对比】叶绿体蛋白用转运肽(transit peptide)引导。","kp":"ch05_s0_1","kps":"核基因编码、胞质核糖体合成;N端导肽+Hsp70解折叠;外膜受体识别;经TOM/TIM入基质;导肽切除;耗ATP"},{"id":"ch05_short_2","modI":1,"q":"简述核孔复合体的结构及核质运输机制。","a":"核孔复合体(NPC)及核质运输：\n\n【结构】\n①所有真核细胞间期核普遍存在；\n②通道直径9-10nm，外径约120nm；\n③八重对称：胞质环(外环，8条短纤毛)、核质面的核篮结构。\n\n【运输功能(双功能)】\n①被动运输：离子、小分子代谢产物、40~60kDa以下小分子自由扩散出入；\n②主动运输：大分子经NLS/NES转运。\n\n【入核机制】\n①亲核蛋白含核定位信号(NLS，富含碱性氨基酸)；\n②胞质中importin(输入蛋白)识别并结合NLS，形成转运复合物；\n③经NPC入核；\n④核内Ran-GTP结合importin，释放货物蛋白；\n⑤importin回收出核。\n\n【出核机制】\n①货物含核输出信号(NES，富含亮氨酸)；\n②exportin识别NES，经NPC出核。\n\n【意义】\n实现核质双向物质交换，是基因表达调控的基础。","kp":"ch05_s1_2","kps":"NPC八重对称;被动<40-60kDa;主动NLS/NES;NLS+importin入核,Ran-GTP释放"},{"id":"ch05_short_3","modI":0,"q":"比较线粒体、叶绿体、过氧化物酶体蛋白的翻译后转运。","a":"三种细胞器蛋白翻译后转运的比较：\n\n| 细胞器 | 引导信号 | 转运子/受体 | 特点 |\n|---|---|---|---|\n| 线粒体 | N端导肽(presequence) | TOM/TIM复合体 | 在内外膜接触点转运，需解折叠 |\n| 叶绿体 | N端转运肽(transit peptide) | TOC/TIC复合体 | 转运肽分2区(基质+类囊体腔) |\n| 过氧化物酶体 | PTS1/PTS2 | Pex蛋白 | 可折叠后导入，有两种发生途径 |\n\n【共同点】\n①蛋白由核基因编码、胞质游离核糖体合成；\n②翻译后转运；\n③依赖N端信号序列；\n④信号序列被切除；\n⑤消耗能量。\n\n【不同点】\n①线粒体需完全解折叠(Hsp70)，过氧化物酶体可折叠导入；\n②叶绿体转运肽分两区，可进入基质和类囊体腔；\n③过氧化物酶体还有ER出芽从头形成途径。\n\n【意义】保证细胞器蛋白正确定位。","kp":"ch05_s0_8","kps":"线粒体(导肽、TOM/TIM);叶绿体(转运肽、TOC/TIC);过氧化物酶体(PTS1/PTS2、Pex、可折叠)"},{"id":"ch05_short_4","modI":1,"q":"简述亲核蛋白入核转运的分子机制。","a":"亲核蛋白入核转运机制：\n\n【关键分子】\n①核定位信号(NLS)：亲核蛋白含有的特殊氨基酸序列，通常富含碱性氨基酸(如PKKKRKV)；\n②importin(输入蛋白)：胞质中的NLS受体；\n③Ran：核质运输的关键GTP酶。\n\n【过程】\n①NLS-亲核蛋白在细胞质中与importin识别并结合，形成转运复合物；\n②转运复合物经核孔复合体(NPC)进入细胞核；\n③核内Ran-GTP结合importin，使其构象改变，释放货物蛋白；\n④importin-Ran-GTP复合物返回细胞质，Ran水解GTP，importin循环使用。\n\n【特点】\n①主动运输，消耗能量；\n②方向性由Ran-GTP的核内浓度梯度决定。\n\n【对照出核】\n核输出信号(NES)+exportin介导出核。\n\n【意义】\n是基因表达调控、细胞周期等的基础。","kp":"ch05_s1_17","kps":"NLS富含碱性氨基酸;importin识别结合;经NPC入核;Ran-GTP释放货物;Ran水解GTP循环"},{"id":"ch05_short_5","modI":0,"q":"简述叶绿体蛋白质的分选途径。","a":"叶绿体蛋白质的分选：\n\n【共同起点】\n细胞质游离核糖体中合成的前体蛋白N端含转运肽(transit peptide)。\n\n【分选途径】\n①叶绿体基质蛋白：转运肽引导经TOC/TIC进入基质→转运肽被切割→折叠成活性蛋白(如Rubisco小亚基)。\n②类囊体腔蛋白：转运肽分2区——N端导向叶绿体基质序列+接下来导向类囊体腔序列→先进入基质，再经类囊体膜进入腔→切除转运肽。\n③类囊体膜蛋白：转运肽引导到类囊体膜并整合。\n\n【特点】\n①转运肽分2区，可两步引导；\n②转运肽最终被切除；\n③部分蛋白需叶绿体自身蛋白(如cpSecA)协助。\n\n【意义】\n保证叶绿体各亚区室蛋白的正确定位，是叶绿体功能的基础。","kp":"ch05_s0_9","kps":"前体N端转运肽;基质蛋白经TOC/TIC入基质切肽折叠;类囊体腔蛋白转运肽分2区先入基质再入腔;类囊体膜蛋白整合"},{"id":"ch05_short_6","modI":2,"q":"简述过氧化物酶体的发生及蛋白导入。","a":"过氧化物酶体的发生及蛋白导入：\n\n【结构】\n单层膜围绕的细胞器，又称微体(microbody)，含氧化酶和过氧化氢酶。\n\n【蛋白合成】\n过氧化物酶体蛋白主要在细胞质基质游离核糖体合成。\n\n【两种发生途径】\n①从头形成：过氧化物酶体的一些膜蛋白Pex3/Pex16来自内质网，由ER出芽形成新的过氧化物酶体；\n②分裂：由已有过氧化物酶体分裂产生。\n\n【蛋白导入】\n①经PTS1(多数蛋白，C端SKL序列)或PTS2(少数)信号；\n②由Pex蛋白(受体)识别；\n③可折叠状态即可导入(与线粒体需解折叠不同)。\n\n【意义】\n保证过氧化物酶体的生物发生和功能(脂肪酸氧化、过氧化氢分解)。","kp":"ch05_s2_1","kps":"单层膜微体含氧化酶/过氧化氢酶;胞质核糖体合成;发生:ER出芽(Pex3/16)+分裂;导入:PTS1/PTS2"},{"id":"ch05_short_x1","modI":0,"q":"比较线粒体蛋白、叶绿体蛋白、过氧化物酶体蛋白和核蛋白在分选信号、转运装置和是否需解折叠上的差异。","a":"①线粒体蛋白：信号为N端导肽，经外膜/内膜转运子TOM/TIM转运，需Hsp70帮助解折叠后以伸展状态进入。②叶绿体蛋白：信号为N端转运肽（可分两区），经TOC/TIC转运，同样需解折叠。③过氧化物酶体蛋白：信号为PTS1（C端）或PTS2（N端），经Pex受体转运，可携折叠构象进入。④核蛋白：信号为核定位信号NLS，经核孔复合体（NPC）转运，以折叠状态通过，由importin/Ran调控。⑤共同点：蛋白均由核基因编码、在胞质游离核糖体合成，依赖信号序列，属翻译后转运。","kps":"线粒体:导肽/TOM-TIM/需解折叠;叶绿体:转运肽/TOC-TIC/需解折叠;过氧化物酶体:PTS/Pex/可折叠;核:NLS/NPC/折叠态;共同:核编码胞质合成、翻译后","type":"比较型","kp":"ch05_s0_0"}],"calc":[{"id":"ch05_calc_1","modI":0,"q":"论述蛋白质翻译后转运的主要途径及分子机制。","a":"翻译后转运将胞质合成的蛋白运往线粒体/叶绿体/过氧化物酶体/细胞核,机制各异","steps":"【定义】\n蛋白质在细胞质游离核糖体完全合成后，再转运至特定细胞器。\n\n【1. 线粒体蛋白转运】\n①N端导肽；②Hsp70+ATP解折叠；③内外膜接触点经TOM/TIM；④导肽切除、重折叠。\n\n【2. 叶绿体蛋白转运】\n①N端转运肽(分2区)；②经TOC/TIC；③分选到基质/类囊体腔/膜；④转运肽切除。\n\n【3. 过氧化物酶体蛋白转运】\n①PTS1/PTS2信号；②Pex受体；③可折叠导入；④两种发生途径(ER出芽/分裂)。\n\n【4. 核孔运输】\n①NLS/NES信号；②importin/exportin受体；③经NPC；④Ran-GTP调控。\n\n【共同点】\n①蛋白由核基因编码、胞质合成；②翻译后转运；③依赖信号序列；④信号被切除(部分)；⑤消耗能量。\n\n【意义】\n保证细胞器蛋白正确定位，维持细胞区室化功能。","kp":"ch05_s0_0","kps":"线粒体:导肽/Hsp70/TOM-TIM/切肽;叶绿体:转运肽/TOC-TIC/分选;过氧化物酶体:PTS1/2/Pex;核孔:NLS/NES/Ran;共同:核编码胞质合成、信号、耗能"},{"id":"ch05_calc_2","modI":1,"q":"论述细胞核与细胞质之间物质运输的机制及意义。","a":"核质运输通过核孔复合体实现,由NLS/NES和Ran-GTP精密调控","steps":"【结构基础】\n核孔复合体(NPC)：通道直径9-10nm，外径约120nm，八重对称(胞质环+核篮)，间期核普遍存在。\n\n【运输类型】\n①被动运输：40~60kDa以下小分子自由扩散；\n②主动运输：大分子经NLS/NES。\n\n【入核机制】\n①亲核蛋白含NLS(富含碱性氨基酸)；\n②胞质importin识别结合NLS；\n③经NPC入核；\n④核内Ran-GTP结合importin释放货物。\n\n【出核机制】\n①货物含NES(富含亮氨酸)；\n②exportin识别NES，经NPC出核。\n\n【方向性】\nRan-GTP在核内浓度高、胞质低→决定运输方向。\n\n【意义】\n①实现核质物质交换(蛋白、RNA)；\n②是基因表达调控的基础(转录因子入核)；\n③参与细胞周期、信号转导、病毒感染等；\n④核质运输异常与疾病相关。","kp":"ch05_s1_6","kps":"NPC(9-10nm/八重对称);被动<40-60kDa;入核NLS+importin+Ran;出核NES+exportin;方向由Ran-GTP梯度决定;意义:核质交换/基因表达/疾病"},{"id":"ch05_calc_3","modI":0,"q":"论述细胞器蛋白靶向信号(分选信号)的多样性及其意义。","a":"不同细胞器使用不同的靶向信号,构成蛋白质分选的'邮政编码'系统","steps":"【各类靶向信号】\n①信号肽(signal peptide)：N端引导蛋白入ER(共翻译转移)；\n②导肽(presequence)：N端引导线粒体蛋白；\n③转运肽(transit peptide)：N端引导叶绿体蛋白(分2区)；\n④PTS1/PTS2：过氧化物酶体蛋白；\n⑤NLS：核定位信号(入核)；\n⑥NES：核输出信号(出核)；\n⑦KDEL：ER驻留/回收信号；\n⑧M6P：溶酶体酶分选信号。\n\n【共同特点】\n①都是特定的氨基酸序列(或糖基修饰)；\n②被特异受体识别；\n③部分在完成任务后被切除；\n④引导蛋白到达正确部位。\n\n【意义】\n①是蛋白质分选的分子基础('邮政编码')；\n②保证细胞区室化、各细胞器功能正常；\n③信号异常导致疾病(如家族性高胆固醇血症、I细胞病、囊性纤维化等)；\n④是基因工程中蛋白定位改造的基础。","kp":"ch05_s0_9","kps":"信号肽/导肽/转运肽/PTS/NLS/NES/KDEL/M6P;共同:特异序列、受体识别、部分切除;意义:分选基础、区室化、疾病、工程"},{"id":"ch05_calc_x2","modI":1,"q":"说明核蛋白经核孔复合体入核的机制，以及Ran-GTP如何决定运输方向。","a":"①亲核蛋白含核定位信号（NLS，富含碱性氨基酸），在胞质被输入蛋白importin（α/β）识别结合。②该复合物经核孔复合体（NPC）的通道入核。③核内Ran-GTP浓度高，结合importinβ使其构象改变，释放货物蛋白；货物在核内发挥作用。④importin-Ran-GTP复合物返回胞质，胞质Ran-GAP使GTP水解为GDP，Ran-GDP释放importin，importin可再次利用。⑤方向性：Ran-GEF在核内（染色质上）使Ran结合GTP，Ran-GAP在胞质使GTP水解；由此形成Ran-GTP的核内外浓度梯度，使入核与出核具有方向性。出核则由exportin识别核输出信号（NES）并依赖核内Ran-GTP。","kps":"NLS+importin识别;经NPC入核;核内Ran-GTP结合importin释放货物;importin循环;Ran-GEF(核)/Ran-GAP(胞质)形成梯度;出核NES+exportin","type":"机制型","kp":"ch05_s1_16"},{"id":"ch05_calc_x3","modI":0,"q":"设计实验验证某蛋白的N端序列是线粒体导肽。","a":"思路：利用融合蛋白定位与缺失分析。①将候选N端序列与报告蛋白（如GFP）融合表达，用荧光显微镜观察融合蛋白是否定位于线粒体（可用MitoTracker等线粒体探针共定位）。②去除该N端序列后同样与GFP融合表达，观察GFP是否弥散于胞质，从而证明该序列对线粒体定位是必需且充分的。③可进一步突变导肽中的碱性氨基酸，检测定位是否丧失。对照：仅表达GFP的细胞（胞质弥散）。预期：含候选N端序列的GFP定位于线粒体，去除或突变后定位消失，说明该N端序列为线粒体导肽。","kps":"N端序列-GFP融合;与线粒体探针共定位;缺失/突变分析;仅GFP对照;预期定位消失","type":"实验设计型","kp":"ch05_s0_2"}],"term":[{"id":"ch05_term_1","modI":0,"term":"导肽(Presequence)","def":"①线粒体蛋白N端的引导序列（定义）。②功能：引导前体蛋白进入线粒体，与膜受体识别（功能）。③特点：完成使命后被切除（特点）。④与叶绿体的转运肽(transit peptide)相对应（对比）。","kps":"踩分点:①定义(1分)②功能(1分)③切除(1分)④与转运肽对比(1分)","kp":"ch05_s0_2"},{"id":"ch05_term_2","modI":0,"term":"转运肽(Transit Peptide)","def":"①叶绿体前体蛋白N端的引导序列（定义）。②特点：可分2区(导向叶绿体基质+导向类囊体腔)，完成使命后被切除（特点）。③功能：引导叶绿体蛋白分选到基质、类囊体腔或膜（功能）。","kps":"踩分点:①定义(1分)②分2区(1分)③切除(1分)④功能(1分)","kp":"ch05_s0_8"},{"id":"ch05_term_3","modI":1,"term":"核孔复合体(NPC)","def":"①真核细胞间期核膜上介导核质物质交换的通道复合体（定义）。②结构：通道直径9-10nm，外径约120nm，八重对称(胞质环+核篮)（结构）。③功能：双功能——被动运输(40~60kDa以下小分子)、主动运输(NLS/NES大分子)（功能）。","kps":"踩分点:①定义(1分)②结构(1分)③双功能(2分)","kp":"ch05_s1_2"},{"id":"ch05_term_4","modI":1,"term":"核定位信号(NLS)","def":"①亲核蛋白含有的、引导其进入细胞核的特殊氨基酸序列（定义）。②特点：通常富含碱性氨基酸(如PKKKRKV)（特点）。③机制：被胞质importin识别结合，经NPC入核（机制）。","kps":"踩分点:①定义(1分)②富含碱性氨基酸(1分)③机制(1分)","kp":"ch05_s1_11"},{"id":"ch05_term_5","modI":1,"term":"核输出信号(NES)","def":"①核内物质输出细胞核的信号序列（定义）。②特点：通常富含亮氨酸（特点）。③机制：被exportin识别，经核孔出核（机制）。","kps":"踩分点:①定义(1分)②富含亮氨酸(1分)③机制(1分)","kp":"ch05_s1_14"},{"id":"ch05_term_6","modI":1,"term":"输入蛋白(Importin)","def":"①胞质溶胶中的NLS受体（定义）。②功能：识别并结合亲核蛋白的NLS，形成转运复合物，经NPC入核（功能）。③调控：核内Ran-GTP结合importin使其释放货物（调控）。","kps":"踩分点:①定义(1分)②功能(1分)③Ran-GTP调控(1分)","kp":"ch05_s1_15"},{"id":"ch05_term_7","modI":1,"term":"Ran蛋白（Ran protein (Ran GTPase)）","def":"①核质运输的关键GTP酶（定义）。②功能：Ran-GTP(主要在核内)结合importin使其释放货物蛋白，决定运输方向（功能）。③意义：Ran-GTP的核内浓度梯度是核质运输方向性的基础（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch05_s1_16"},{"id":"ch05_term_8","modI":0,"term":"TOM/TIM复合体（TOM/TIM complex (translocase of the outer/inner membrane)）","def":"①线粒体外膜(TOM)和内膜(TIM)的蛋白转运子复合体（定义）。②功能：前体蛋白经TOM进入、经TIM进入线粒体基质（功能）。③位置：在内外膜接触点协同工作（位置）。","kps":"踩分点:①定义(1分)②功能(2分)③位置(1分)","kp":"ch05_s0_4"},{"id":"ch05_term_9","modI":2,"term":"过氧化物酶体(Peroxisome)","def":"①单层膜围绕的细胞器，又称微体(microbody)（定义）。②组成：含氧化酶和过氧化氢酶（组成）。③发生：两种途径——ER出芽从头形成、已有酶体分裂（发生）。④蛋白导入：经PTS1/PTS2信号（导入）。","kps":"踩分点:①定义(1分)②组成(1分)③发生(1分)④PTS信号(1分)","kp":"ch05_s2_0"},{"id":"ch05_term_10","modI":0,"term":"分子伴侣Hsp70在线粒体蛋白转运中的作用（Role of the chaperone Hsp70 in mitochondrial protein transport）","def":"①Hsp70在胞质中与前体蛋白结合（定义）。②功能：消耗ATP使前体蛋白解折叠为松散结构，才能被导入线粒体（功能）。③意义：线粒体只允许解折叠蛋白进入（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch05_s0_7"},{"id":"ch05_term_11","modI":0,"term":"共翻译转移与翻译后转移（Co-translational translocation and post-translational translocation）","def":"①共翻译转移：蛋白边合成边经信号肽引导入ER(分泌蛋白、膜蛋白、溶酶体酶)（定义）。②翻译后转移：蛋白在游离核糖体完全合成后转运至线粒体、叶绿体、过氧化物酶体、细胞核（定义）。③区别：转移时间不同、信号序列不同、受体不同（区别）。","kps":"踩分点:①共翻译(1分)②翻译后(1分)③区别(2分)","kp":"ch05_s0_0"},{"id":"ch05_term_12","modI":1,"term":"核篮结构（Nuclear basket structure）","def":"①核孔复合体核质面一侧的篮状结构（定义）。②组成：由8条纤丝汇聚成环（组成）。③功能：参与核质物质运输（功能）。","kps":"踩分点:①定义(1分)②组成(1分)③功能(1分)","kp":"ch05_s1_5"},{"id":"ch05_term_13","modI":2,"term":"PTS信号（PTS signal (peroxisomal targeting signal)）","def":"①过氧化物酶体蛋白的靶向信号(PTS1/PTS2)（定义）。②PTS1：多数过氧化物酶体蛋白，C端SKL序列；PTS2：少数蛋白，N端（分类）。③功能：由Pex蛋白受体识别，引导蛋白导入过氧化物酶体（功能）。","kps":"踩分点:①定义(1分)②PTS1/PTS2(2分)③功能(1分)","kp":"ch05_s2_2"},{"id":"ch05_term_14","modI":0,"term":"接触点(Contact Site)","def":"①线粒体内外膜靠近的区域（定义）。②功能：前体蛋白在此经TOM/TIM转运到线粒体基质（功能）。③意义：是线粒体蛋白导入的关键位点（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch05_s0_3"},{"id":"ch05_term_15","modI":0,"term":"细胞器蛋白靶向信号（Organelle protein targeting signal）","def":"①引导蛋白质到达特定细胞器的氨基酸序列（定义）。②种类：信号肽(ER)、导肽(线粒体)、转运肽(叶绿体)、PTS(过氧化物酶体)、NLS/NES(核)、KDEL(ER驻留)、M6P(溶酶体)（种类）。③意义：是蛋白质分选的'邮政编码'，信号异常导致疾病（意义）。","kps":"踩分点:①定义(1分)②种类(2分)③意义(1分)","kp":"ch05_s0_7"}],"preview":{"main":"本章讲述蛋白质在细胞质合成后如何被定向转运到线粒体、叶绿体、细胞核和过氧化物酶体等膜包被细胞器。核心逻辑是：不同细胞器使用不同的信号序列和转运机制，其中线粒体和叶绿体依赖解折叠转运，细胞核通过核孔复合体进行信号介导的主动运输，过氧化物酶体则有独特的形成途径。理解这些机制是理解细胞区室化和蛋白质分选的基础。","questions":["线粒体蛋白的转运为什么要求前体蛋白必须解折叠？Hsp70在其中起什么作用？","线粒体膜的转运子（TOM/TIM）如何协同完成基质蛋白的导入？接触点转运意味着什么？","叶绿体蛋白的转运肽如何决定蛋白最终定位到基质、类囊体膜还是类囊体腔？双区转运肽有何特殊之处？","核孔复合体的结构（胞质环、核篮等）如何支持其双向运输功能？","核定位信号（NLS）和核输出信号（NES）分别如何被识别？Ran-GTP如何驱动入核和出核的方向性？","过氧化物酶体的两种形成途径分别是什么？其蛋白导入与线粒体、叶绿体有何本质区别？"],"answers":["线粒体膜通道窄，未解折叠蛋白进不去；胞质 Hsp70 结合前体并耗 ATP 把它拉松（去折叠）才能导入，进入后再由基质 Hsp70 帮忙折叠。","前体先经外膜 TOM 识别、再经内膜 TIM 进入基质；两转运子在内外膜接触点处协同工作，使前体一次跨越两层膜——即接触点转运。","叶绿体蛋白 N 端转运肽引导进入叶绿体（基质蛋白）后被切除；类囊体腔蛋白的转运肽分两区，先导向基质、再导向类囊体腔（双区转运肽），实现分层定位。","核孔复合体由胞质环、核篮、辐等构成通道：小分子可自由扩散，大分子凭信号主动进出，从而支持双向运输。","NLS 被 importin 识别带入核，NES 引导出核；核内 Ran-GTP 结合 importin 促其释放货物，胞质 Ran-GDP 使其载货，Ran-GTP/GDP 在核内外的不对称分布驱动方向性。","两种形成途径：由 ER 出芽从头形成、由已有过氧化物酶体分裂；其蛋白在胞质合成后经 PTS1/PTS2 信号导入，部分膜来自 ER——与线粒体/叶绿体（解折叠、经 TOM/TIM）本质不同。"]},"appcards":[{"front":"简述线粒体蛋白质翻译后转运的过程。","back":"线粒体蛋白质的翻译后转运：\n\n【特点】\n线粒体绝大多数蛋白由核基因编码，在胞质游离核糖体合成后转运。\n\n【过程】\n①在细胞质基质中，含N端导肽(presequence)的前体蛋白与Hsp70结合，ATP→ADP，解折叠为松散结构；\n②前体蛋白的导肽与线粒体外膜受体识别；\n③在内外膜接触点，经外膜转运子TOM复合体进入；\n④经内膜转运子TIM复合体进入基质；\n⑤导肽被切除，蛋白在基质中重新折叠成活性形式；\n⑥部分蛋白进一步分选到内膜、膜间隙或外膜。\n\n【要点】\n①需N端导肽；②必须解折叠才能导入；③发生在内外膜接触点；④消耗能量(ATP)。\n\n【对比】叶绿体蛋白用转运肽(transit peptide)引导。","points":"","mod":0,"modName":"模块一：线粒体与叶绿体蛋白转运","level":"掌握","src":"题库"},{"front":"简述核孔复合体的结构及核质运输机制。","back":"核孔复合体(NPC)及核质运输：\n\n【结构】\n①所有真核细胞间期核普遍存在；\n②通道直径9-10nm，外径约120nm；\n③八重对称：胞质环(外环，8条短纤毛)、核质面的核篮结构。\n\n【运输功能(双功能)】\n①被动运输：离子、小分子代谢产物、40~60kDa以下小分子自由扩散出入；\n②主动运输：大分子经NLS/NES转运。\n\n【入核机制】\n①亲核蛋白含核定位信号(NLS，富含碱性氨基酸)；\n②胞质中importin(输入蛋白)识别并结合NLS，形成转运复合物；\n③经NPC入核；\n④核内Ran-GTP结合importin，释放货物蛋白；\n⑤importin回收出核。\n\n【出核机制】\n①货物含核输出信号(NES，富含亮氨酸)；\n②exportin识别NES，经NPC出核。\n\n【意义】\n实现核质双向物质交换，是基因表达调控的基础。","points":"","mod":1,"modName":"模块二：核孔运输","level":"掌握","src":"题库"},{"front":"比较线粒体、叶绿体、过氧化物酶体蛋白的翻译后转运。","back":"三种细胞器蛋白翻译后转运的比较：\n\n| 细胞器 | 引导信号 | 转运子/受体 | 特点 |\n|---|---|---|---|\n| 线粒体 | N端导肽(presequence) | TOM/TIM复合体 | 在内外膜接触点转运，需解折叠 |\n| 叶绿体 | N端转运肽(transit peptide) | TOC/TIC复合体 | 转运肽分2区(基质+类囊体腔) |\n| 过氧化物酶体 | PTS1/PTS2 | Pex蛋白 | 可折叠后导入，有两种发生途径 |\n\n【共同点】\n①蛋白由核基因编码、胞质游离核糖体合成；\n②翻译后转运；\n③依赖N端信号序列；\n④信号序列被切除；\n⑤消耗能量。\n\n【不同点】\n①线粒体需完全解折叠(Hsp70)，过氧化物酶体可折叠导入；\n②叶绿体转运肽分两区，可进入基质和类囊体腔；\n③过氧化物酶体还有ER出芽从头形成途径。\n\n【意义】保证细胞器蛋白正确定位。","points":"","mod":0,"modName":"模块一：线粒体与叶绿体蛋白转运","level":"掌握","src":"题库"},{"front":"简述亲核蛋白入核转运的分子机制。","back":"亲核蛋白入核转运机制：\n\n【关键分子】\n①核定位信号(NLS)：亲核蛋白含有的特殊氨基酸序列，通常富含碱性氨基酸(如PKKKRKV)；\n②importin(输入蛋白)：胞质中的NLS受体；\n③Ran：核质运输的关键GTP酶。\n\n【过程】\n①NLS-亲核蛋白在细胞质中与importin识别并结合，形成转运复合物；\n②转运复合物经核孔复合体(NPC)进入细胞核；\n③核内Ran-GTP结合importin，使其构象改变，释放货物蛋白；\n④importin-Ran-GTP复合物返回细胞质，Ran水解GTP，importin循环使用。\n\n【特点】\n①主动运输，消耗能量；\n②方向性由Ran-GTP的核内浓度梯度决定。\n\n【对照出核】\n核输出信号(NES)+exportin介导出核。\n\n【意义】\n是基因表达调控、细胞周期等的基础。","points":"","mod":1,"modName":"模块二：核孔运输","level":"掌握","src":"题库"},{"front":"简述叶绿体蛋白质的分选途径。","back":"叶绿体蛋白质的分选：\n\n【共同起点】\n细胞质游离核糖体中合成的前体蛋白N端含转运肽(transit peptide)。\n\n【分选途径】\n①叶绿体基质蛋白：转运肽引导经TOC/TIC进入基质→转运肽被切割→折叠成活性蛋白(如Rubisco小亚基)。\n②类囊体腔蛋白：转运肽分2区——N端导向叶绿体基质序列+接下来导向类囊体腔序列→先进入基质，再经类囊体膜进入腔→切除转运肽。\n③类囊体膜蛋白：转运肽引导到类囊体膜并整合。\n\n【特点】\n①转运肽分2区，可两步引导；\n②转运肽最终被切除；\n③部分蛋白需叶绿体自身蛋白(如cpSecA)协助。\n\n【意义】\n保证叶绿体各亚区室蛋白的正确定位，是叶绿体功能的基础。","points":"","mod":0,"modName":"模块一：线粒体与叶绿体蛋白转运","level":"掌握","src":"题库"},{"front":"简述过氧化物酶体的发生及蛋白导入。","back":"过氧化物酶体的发生及蛋白导入：\n\n【结构】\n单层膜围绕的细胞器，又称微体(microbody)，含氧化酶和过氧化氢酶。\n\n【蛋白合成】\n过氧化物酶体蛋白主要在细胞质基质游离核糖体合成。\n\n【两种发生途径】\n①从头形成：过氧化物酶体的一些膜蛋白Pex3/Pex16来自内质网，由ER出芽形成新的过氧化物酶体；\n②分裂：由已有过氧化物酶体分裂产生。\n\n【蛋白导入】\n①经PTS1(多数蛋白，C端SKL序列)或PTS2(少数)信号；\n②由Pex蛋白(受体)识别；\n③可折叠状态即可导入(与线粒体需解折叠不同)。\n\n【意义】\n保证过氧化物酶体的生物发生和功能(脂肪酸氧化、过氧化氢分解)。","points":"","mod":2,"modName":"模块三：过氧化物酶体","level":"掌握","src":"题库"},{"front":"论述蛋白质翻译后转运的主要途径及分子机制。","back":"【定义】\n蛋白质在细胞质游离核糖体完全合成后，再转运至特定细胞器。\n\n【1. 线粒体蛋白转运】\n①N端导肽；②Hsp70+ATP解折叠；③内外膜接触点经TOM/TIM；④导肽切除、重折叠。\n\n【2. 叶绿体蛋白转运】\n①N端转运肽(分2区)；②经TOC/TIC；③分选到基质/类囊体腔/膜；④转运肽切除。\n\n【3. 过氧化物酶体蛋白转运】\n①PTS1/PTS2信号；②Pex受体；③可折叠导入；④两种发生途径(ER出芽/分裂)。\n\n【4. 核孔运输】\n①NLS/NES信号；②importin/exportin受体；③经NPC；④Ran-GTP调控。\n\n【共同点】\n①蛋白由核基因编码、胞质合成；②翻译后转运；③依赖信号序列；④信号被切除(部分)；⑤消耗能量。\n\n【意义】\n保证细胞器蛋白正确定位，维持细胞区室化功能。","points":"","mod":0,"modName":"模块一：线粒体与叶绿体蛋白转运","level":"掌握","src":"题库"},{"front":"论述细胞核与细胞质之间物质运输的机制及意义。","back":"【结构基础】\n核孔复合体(NPC)：通道直径9-10nm，外径约120nm，八重对称(胞质环+核篮)，间期核普遍存在。\n\n【运输类型】\n①被动运输：40~60kDa以下小分子自由扩散；\n②主动运输：大分子经NLS/NES。\n\n【入核机制】\n①亲核蛋白含NLS(富含碱性氨基酸)；\n②胞质importin识别结合NLS；\n③经NPC入核；\n④核内Ran-GTP结合importin释放货物。\n\n【出核机制】\n①货物含NES(富含亮氨酸)；\n②exportin识别NES，经NPC出核。\n\n【方向性】\nRan-GTP在核内浓度高、胞质低→决定运输方向。\n\n【意义】\n①实现核质物质交换(蛋白、RNA)；\n②是基因表达调控的基础(转录因子入核)；\n③参与细胞周期、信号转导、病毒感染等；\n④核质运输异常与疾病相关。","points":"","mod":1,"modName":"模块二：核孔运输","level":"掌握","src":"题库"},{"front":"论述细胞器蛋白靶向信号(分选信号)的多样性及其意义。","back":"【各类靶向信号】\n①信号肽(signal peptide)：N端引导蛋白入ER(共翻译转移)；\n②导肽(presequence)：N端引导线粒体蛋白；\n③转运肽(transit peptide)：N端引导叶绿体蛋白(分2区)；\n④PTS1/PTS2：过氧化物酶体蛋白；\n⑤NLS：核定位信号(入核)；\n⑥NES：核输出信号(出核)；\n⑦KDEL：ER驻留/回收信号；\n⑧M6P：溶酶体酶分选信号。\n\n【共同特点】\n①都是特定的氨基酸序列(或糖基修饰)；\n②被特异受体识别；\n③部分在完成任务后被切除；\n④引导蛋白到达正确部位。\n\n【意义】\n①是蛋白质分选的分子基础('邮政编码')；\n②保证细胞区室化、各细胞器功能正常；\n③信号异常导致疾病(如家族性高胆固醇血症、I细胞病、囊性纤维化等)；\n④是基因工程中蛋白定位改造的基础。","points":"","mod":0,"modName":"模块一：线粒体与叶绿体蛋白转运","level":"掌握","src":"题库"},{"front":"线粒体蛋白与叶绿体蛋白的N端信号序列有何异同？","back":"同：均为N端信号序列，引导后翻译转运，进入后切除；异：线粒体称导肽，叶绿体称转运肽；叶绿体类囊体腔蛋白转运肽含双区，分两步引导。","points":"N端信号；导肽/转运肽；切除；双区","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么只有去折叠的蛋白才能被导入线粒体？","back":"线粒体膜转运通道狭窄；折叠蛋白体积大无法通过TOM/TIM通道；胞质Hsp70结合前体蛋白，ATP水解使其解折叠为松散结构后才能导入。","points":"通道狭窄；Hsp70；ATP；解折叠","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"线粒体基质蛋白导入过程中，导肽被切除有什么意义？","back":"导肽切除使蛋白失去入线粒体信号；避免成熟蛋白被再次转运；允许蛋白折叠成活性构象；保证蛋白定位于基质。","points":"失去信号；避免再转运；折叠；定位","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较线粒体外膜转运子TOM与内膜转运子TIM的功能。","back":"TOM位于外膜，识别并结合前体蛋白N端导肽，使其进入膜间隙；TIM位于内膜，接收前体蛋白并转运至基质；二者在接触点协同完成跨膜转运。","points":"TOM外膜；识别导肽；TIM内膜；接触点协同","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么线粒体蛋白转运发生在内外膜接触点？","back":"接触点是内外膜靠近的区域；TOM与TIM在此对齐形成连续通道；前体蛋白可一次性穿过两层膜；提高转运效率，避免膜间隙中停留。","points":"内外膜靠近；TOM/TIM对齐；连续通道；效率","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明叶绿体蛋白的多层次分选。","back":"Rubisco小亚基由核基因编码，转运肽引导入基质后切除并折叠；类囊体腔蛋白转运肽含双区，先入基质再入类囊体腔；类囊体膜蛋白另有导入途径。","points":"Rubisco基质；类囊体腔双区；类囊体膜；多层次","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"叶绿体类囊体腔蛋白的转运肽为什么需要双区结构？","back":"N端第一区导向叶绿体基质；第二区导向类囊体腔；分两步引导，先进入基质再进入类囊体腔；保证蛋白正确定位于类囊体腔。","points":"双区；基质；类囊体腔；两步","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若细胞质Hsp70功能被抑制，线粒体蛋白导入会怎样？","back":"前体蛋白无法解折叠；保持折叠状态不能通过TOM/TIM通道；线粒体基质蛋白导入受阻；线粒体功能受损。","points":"不能解折叠；通道受阻；导入受阻；功能受损","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"核孔复合体NPC的被动运输与主动运输有何区别？","back":"被动运输：离子、小分子代谢物、约40~60kDa以下小分子自由扩散；主动运输：大分子经NLS/NES信号、消耗能量转运。","points":"小分子自由扩散；大分子；NLS/NES；耗能","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"核定位信号NLS有什么特点？举例说明其作用。","back":"NLS通常富含碱性氨基酸，如PKKKRKV；引导亲核蛋白入核；NLS与importin结合形成转运复合物；经NPC入核后Ran-GTP使其释放。","points":"碱性氨基酸；PKKKRKV；importin；Ran-GTP","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较NLS与NES的功能差异。","back":"NLS引导蛋白入核，富含碱性氨基酸；NES引导核内物质出核，通常富含亮氨酸；二者分别介导入核和出核转运。","points":"NLS入核；碱性；NES出核；亮氨酸","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么亲核蛋白入核需要importin？","back":"亲核蛋白不能直接穿过核孔；importin是水溶性NLS受体；识别并结合NLS形成转运复合物；介导蛋白通过NPC进入核内。","points":"不能直接穿过；NLS受体；转运复合物；NPC","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"Ran-GTP在核质运输中有什么作用？","back":"Ran-GTP主要在核内；结合importin使其构象改变；释放货物蛋白；Ran是核质运输关键调控GTP酶；维持入核与出核方向性。","points":"核内；结合importin；释放货物；GTP酶；方向性","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若Ran-GTP水解被抑制，核质运输会怎样？","back":"importin无法释放货物蛋白；入核转运复合物不能解离；货物蛋白不能释放到核内；核质运输受阻。","points":"不能释放；复合物不解离；货物滞留；运输受阻","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"过氧化物酶体蛋白的PTS1与PTS2信号有何不同？","back":"PTS1位于C端，多数过氧化物酶体基质蛋白使用；PTS2位于N端，少数蛋白使用；二者均引导蛋白导入过氧化物酶体。","points":"PTS1 C端；PTS2 N端；引导导入；基质蛋白","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"过氧化物酶体有哪两种形成途径？","back":"从头形成：由内质网出芽形成；分裂形成：由已有过氧化物酶体分裂；膜蛋白Pex3/Pex16来自内质网；蛋白经PTS信号导入。","points":"ER出芽；分裂；Pex3/Pex16；PTS","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说过氧化物酶体既是自主形成又依赖内质网？","back":"部分膜蛋白Pex3/Pex16来自内质网；新过氧化物酶体可由ER出芽从头形成；也可由已有过氧化物酶体分裂；蛋白主要在胞质游离核糖体合成后导入。","points":"Pex3/Pex16；ER出芽；分裂；胞质合成","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明后翻译转运在细胞中的普遍性。","back":"线粒体基质蛋白：胞质合成后经TOM/TIM导入；叶绿体Rubisco小亚基：经转运肽入基质；亲核蛋白：经NLS/importin入核；过氧化物酶体蛋白：经PTS导入。","points":"线粒体；叶绿体；细胞核；过氧化物酶体","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"线粒体蛋白定向运输中，导肽与受体识别有什么意义？","back":"保证蛋白特异性识别线粒体；导肽与TOM受体结合启动转运；避免其他蛋白误入；确保蛋白正确定位于线粒体。","points":"特异性；TOM受体；启动转运；正确定位","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较线粒体与叶绿体蛋白转运的异同。","back":"同：核基因编码、胞质合成、N端信号、后翻译转运、信号切除；异：线粒体称导肽，叶绿体称转运肽；叶绿体有类囊体腔双区转运肽。","points":"核基因；N端信号；后翻译；导肽/转运肽；双区","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"核孔复合体NPC的结构如何支持其双功能？","back":"胞质环有8条短纤毛伸向胞质；核质面有核篮由8条纤丝汇聚成环；中央通道直径9-10nm；结构支持被动扩散和主动转运。","points":"胞质环；核篮；中央通道；被动/主动","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若NPC的核篮结构缺失，可能影响什么？","back":"核质面纤丝汇聚结构异常；可能影响核输出或入核复合物定位；大分子主动转运效率下降；核质物质交换受阻。","points":"核篮缺失；复合物定位；主动转运；交换受阻","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么大蛋白入核需要NLS而小分子不需要？","back":"小分子约40~60kDa以下可经NPC自由扩散；大蛋白不能自由通过；需NLS与importin结合；经主动运输消耗能量入核。","points":"小分子自由扩散；大蛋白不能；NLS；主动运输","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明NLS和NES在细胞中的协同作用。","back":"染色质包装蛋白含NLS，经importin入核；核内某些分子含NES，经exportin出核；Ran-GTP调控方向；实现核质双向运输。","points":"NLS入核；NES出核；Ran-GTP；双向","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若线粒体TOM复合体功能缺失，细胞会怎样？","back":"前体蛋白不能识别线粒体外膜；不能进入膜间隙；TIM无法接收前体蛋白；线粒体基质蛋白导入受阻；线粒体功能受损。","points":"不能识别；不能进入；TIM受阻；线粒体受损","mod":null,"modName":"应用综合","level":"掌握","src":"生成"}],"jyq":[{"id":"jyq_ch05_1","kind":"mcq","q":"线粒体外膜上的哪一种蛋白，促进线粒体蛋白前体从内外膜接触点插人（）。","o":["A. 受体","B. GIP","C. 解折叠","D. 孔蛋白"],"a":"B","src":"南京师范大学，2008年","kp":null,"e":"线粒体外膜上的通用插入孔（GIP）蛋白，促进蛋白前体从内外膜接触点插入。","oe":["错误：受体负责识别前体，题问的是促进前体插入接触点的蛋白。","正确：GIP（通用插入蛋白）促进前体从内外膜接触点插入。","错误：解折叠由胞质中的分子伴侣完成，不是外膜蛋白。","错误：孔蛋白构成外膜通道，与蛋白前体插入接触点无直接关系。"]},{"id":"jyq_ch05_2","kind":"mcq","q":"下列不属于高尔基体复合体功能的是（）。","o":["A. 浓缩溶酶体的酶，帮助初级溶酶体的形成","B. 运送膜蛋白定位蛋白至细胞膜上","C. 将内质网上所需的蛋白质运回","D. 分泌糖蛋白E.帮助线粒体内外膜上的蛋白运输"],"a":"","src":"湖北大学，2008年","kp":null,"e":"高尔基体负责溶酶体酶浓缩、膜蛋白运输、内质网蛋白回收和糖蛋白分泌；线粒体蛋白运输由其自身系统完成，故E不属其功能。","oe":["浓缩溶酶体酶、帮助形成初级溶酶体是高尔基体的功能。","将膜蛋白运送并定位到细胞膜上是高尔基体的功能。","将内质网所需的蛋白质运回内质网是高尔基体的回收功能。","分泌糖蛋白是高尔基体功能，而E帮助线粒体蛋白运输不属其功能。"]},{"id":"jyq_ch05_3","kind":"short","q":"某些特殊的氨基酸序列可以作为分选标记影响蛋白质的定位，C端具有序列的蛋白质通常驻留在内质网腔，而带有序列的蛋白质则会被输送到。","a":"PKKKRKV；细胞核。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch05_4","kind":"judge","q":"蛋白核定位信号（nuclearlocalizationsignal）富含碱性氨基酸。","a":"对","src":"南京师范大学，2008年","kp":null,"oe":["NLS核心序列富含赖氨酸、精氨酸等碱性氨基酸，如SV40大T抗原的PKKKRKV。","若以为NLS富含酸性氨基酸则错，其正电性利于与核孔复合体结合而入核。"]},{"id":"jyq_ch05_5","kind":"short","q":"入核信号又称核定位信号（nuclearlocalizationsignal，NLS）","a":"是另一种形式的信号肽，这种信号肽序列可以位于多肽序列的任何部分。一般含有4～8个氨基酸，且没有专一性，作用是帮助亲核蛋白进入细胞核，这种人核信号与导肽的区别在于：①由含水的核孔通道来鉴别；②入核信号是蛋白质的永久性部分，在引导人核过程中，并不被切除，可以反复使用，有利于细胞分裂后核蛋白重新人核。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch05_6","kind":"mcq","q":"核定位信号一般由短的氨基酸序列组成，它定位在核蛋白氨基酸序列（）。","o":["A. N末端","B. C末端","C. 中部","D. 任何部位"],"a":"D","src":"南京师范大学，2008年","kp":null,"e":"核定位信号由短氨基酸序列组成，可位于核蛋白的N端、C端或中部，位置不固定。","oe":["错误：NLS并非只位于N末端，其在序列中的位置多变。","错误：C末端只是可能位置之一，不是唯一位置。","错误：中部也只是可能位置，NLS没有固定的部位。","正确：NLS可存在于核蛋白氨基酸序列的任何部位。"]},{"id":"jyq_ch05_7","kind":"short","q":"论述题：细胞核孔复合体是由哪几部分组成。简述蛋白质进人细胞核过程。如何通过实验证明上述过程。","a":"①核孔复合体的基本组分包括孔环颗粒、周边颗粒、中央颗粒和细纤丝。孔环颗粒共有8对，呈放射状排列在核孔周围。每个孔环颗粒的直径为10～25nm，由微细粒子和纤丝盘绕而成。周边颗粒位于内、外核膜交界处，核孔的周缘以细纤丝与相对应的内、外孔环颗粒相连。中央颗粒位于核孔中央，呈粒状或棒状，直径为5～30nm，也是由细纤丝连接孔环颗粒和周边颗粒；②核孔复合体中央的核孔是含水通道，允许水溶性物质进出核膜内外。因此，核孔复合体的功能在于调节核孔大小，实现细胞核与细胞质之","src":"华中农业大学，2009年","kp":null},{"id":"jyq_ch05_8","kind":"short","q":"阐述亲核蛋白进人细胞核的机制。","a":"亲核蛋白具有一段特殊的氨基酸序列，称为核定位信号。胞质溶胶中有核输人受体。核蛋白由细胞质溶质进人核的机制如下：①核输人受体与核蛋白结合成复合物；②复合物与核孔伸出的原纤维结合，移向核孔；③核蛋白与核孔结合，由GTt水解供能，打开核孔，复合物穿过核孔进人核；④核输人受体与核蛋白分离，受体返回细胞质溶质。","src":"山东大学，2006年","kp":null}],"outline":["后翻译转运","线粒体蛋白导入(TOM/TIM)","叶绿体蛋白分选","核孔运输(NLS/NES/Ran)","过氧化物酶体"],"outlineMap":[0,0,0,1,0],"narrative":"【问题】胞质合成的蛋白如何定向进入线粒体、叶绿体、核与过氧化物酶体？\n【线粒体】前体蛋白 N 端导肽是“地址”，先经外膜 TOM、再经内膜 TIM，在内外膜接触点处一次跨膜进入基质，导肽被切除、蛋白折叠。体外实验：带导肽前体可被分离线粒体导入而成熟蛋白不能，加蛋白酶时导入后受膜保护的蛋白不被降解——证明“导肽引导 + 跨膜导入”。胞质 Hsp70 耗 ATP 把前体拉松去折叠（膜通道窄），基质 Hsp70 再帮其折叠。\n【叶绿体】转运肽引导进入，类囊体腔蛋白带双区转运肽，先导向基质、再导向类囊体腔，实现分层定位。\n【细胞核】核孔复合体（由胞质环、核篮等构成，冷冻蚀刻电镜显示八重对称）是双向通道：小分子自由扩散，大分子凭 NLS/NES，由 importin 与 Ran-GTP/GDP 在核内外的不对称分布驱动主动进出。\n【过氧化物酶体】蛋白在胞质合成后经 PTS1/PTS2 导入，可由 ER 出芽从头形成或由已有酶体分裂——与线粒体/叶绿体的解折叠跨膜机制本质不同。"};